/**
 * What every primitive of audio/ui shares and the kernel does not do: parts
 * named in kebab case, a value reported as `onValueChange` and
 * `onValueCommitted`, one pointer gesture at a time, and a native input
 * hidden from sight. The primitives import it from `../primitive`.
 */
import {
  bindDrag,
  type ChangeSource,
  createChange,
  definePrimitive as definePrimitiveOf,
  dispatch,
  type PointerSample,
  type PrimitiveContext,
} from "@ui-sdk/core";

/** A boolean as a data attribute: present and empty, or absent. */
export const flag = (on: boolean) => (on ? "" : undefined);

/** What a change reports to `onValueChange`, beside the value. */
export interface ChangeDetails {
  cancel: () => void;
  event?: Event;
  /** The point or segment that moved, for a control that has several. */
  index?: number;
  reason: string;
  source?: string;
}

/** What a commit reports to `onValueCommitted`, beside the value. */
export interface CommitDetails {
  event?: Event;
  index?: number;
  reason: string;
}

/** How a native input is hidden while it keeps the focus, the keys and the name. */
export const VISUALLY_HIDDEN = {
  border: "0",
  "clip-path": "inset(50%)",
  height: "1px",
  margin: "-1px",
  overflow: "hidden",
  padding: "0",
  position: "absolute",
  "white-space": "nowrap",
  width: "1px",
};

/**
 * How a change came about, when its event says. The kernel reads it from
 * input it tracks, so the first interaction would report "programmatic"
 * without this. With no event, the kernel decides, and an agent's change
 * stays the agent's.
 */
export function sourceOf(event?: Event): ChangeSource | undefined {
  if (typeof PointerEvent !== "undefined" && event instanceof PointerEvent) {
    return event.pointerType === "touch" || event.pointerType === "pen"
      ? event.pointerType
      : "mouse";
  }
  if (event instanceof MouseEvent) {
    return "mouse";
  }
  if (event instanceof KeyboardEvent) {
    return "keyboard";
  }
}

/** A change or a commit's details: the reason, the event, and who caused it when the event says. */
function detailsOf(reason: string, event?: Event, extra?: object) {
  const source = sourceOf(event);
  return { event, reason, ...(source ? { source } : {}), ...extra };
}

/**
 * How a primitive whose state holds a `value` reports it: `report` fires
 * `onValueChange` and keeps the value unless an app refused it, `commit`
 * fires `onValueCommitted`, and `setAtOnce` does both, for a change that is
 * over as soon as it is made (a key, a typed value, the wheel, a reset). It
 * skips a value `same` finds equal to the one `displayed` shows; with no
 * `same`, every value is reported, even an unchanged one. `extra` goes into
 * the details, such as the `index` of the point that moved.
 */
export function createReporter<State extends { value: Value }, Value>(
  context: PrimitiveContext<any, State, any>,
  displayed: (state: State) => Value,
  same?: (a: Value, b: Value) => boolean
) {
  const change = createChange(context);
  const state = () => context.store.get() as State;
  const commit = (
    value: Value,
    reason: string,
    event?: Event,
    extra?: object
  ) => {
    dispatch(
      context,
      "onValueCommitted",
      value,
      detailsOf(reason, event, extra)
    );
  };
  const report = (
    value: Value,
    reason: string,
    event?: Event,
    extra?: object
  ) =>
    change("value", value as never, detailsOf(reason, event, extra) as never);
  const setAtOnce = (
    value: Value,
    reason: string,
    event?: Event,
    extra?: object
  ) => {
    if (same?.(value, displayed(state()))) {
      return;
    }
    if (report(value, reason, event, extra)) {
      commit(value, reason, event, extra);
    }
  };
  return { commit, report, setAtOnce, state };
}

/** Two numbers as one text: a comma between them, or a semicolon where the comma is the decimal mark. */
export function formatPair(formatter: Intl.NumberFormat, a: number, b: number) {
  const decimalComma = formatter
    .formatToParts(1.5)
    .some((part) => part.type === "decimal" && part.value === ",");
  return `${formatter.format(a)}${decimalComma ? "; " : ", "}${formatter.format(b)}`;
}

/** Where in an interval a curve is checked against its chord, how many times an interval may be halved, and a ceiling on the vertices of one curve. */
const PROBES = [0.25, 0.5, 0.75];
const MAX_DEPTH = 8;
const MAX_SAMPLES = 4096;

/**
 * The vertices of a polyline that draws `f(t)` for `t` from 0 to 1 without
 * straying more than `tolerance` from it: it starts from `grid` and halves
 * every interval whose curve leaves its chord. `width` is how wide `t` from 0
 * to 1 spans in the box the curve is drawn in.
 */
export function adaptiveSamples(
  f: (t: number) => number,
  grid: readonly number[],
  tolerance: number,
  width = 1
) {
  const samples: [number, number][] = [];
  let budget = MAX_SAMPLES - grid.length;
  const refine = (
    from: number,
    start: number,
    to: number,
    end: number,
    depth: number
  ) => {
    if (depth >= MAX_DEPTH || budget <= 0) {
      return;
    }
    let stray = 0;
    let middle = Number.NaN;
    for (const probe of PROBES) {
      const value = f(from + (to - from) * probe);
      stray = Math.max(
        stray,
        Math.abs(value - (start + (end - start) * probe))
      );
      if (probe === 0.5) {
        middle = value;
      }
    }
    const slope = (end - start) / ((to - from) * width);
    if (stray / Math.sqrt(1 + slope * slope) <= tolerance) {
      return;
    }
    const half = (from + to) / 2;
    budget -= 1;
    refine(from, start, half, middle, depth + 1);
    samples.push([half, middle]);
    refine(half, middle, to, end, depth + 1);
  };
  const values = grid.map(f);
  grid.forEach((t, index) => {
    const value = values[index] ?? 0;
    samples.push([t, value]);
    const next = grid[index + 1];
    if (next !== undefined) {
      refine(t, value, next, values[index + 1] ?? 0, 0);
    }
  });
  return samples;
}

/**
 * What a change reports: why it happened (`reason`), the event behind it,
 * and `cancel()` to refuse the change.
 */
export interface ChangeEventDetails<Reason extends string, E extends Event> {
  cancel: () => void;
  event: E;
  readonly isCanceled: boolean;
  reason: Reason;
}

/** What a commit reports once a gesture ends: why it happened and the event behind it. */
export interface CommitEventDetails<Reason extends string, E extends Event> {
  event: E;
  reason: Reason;
}

/** The details of a change for `reason` and `event`, with `cancel()` to refuse it. */
export function createChangeEventDetails<
  Reason extends string,
  E extends Event,
>(reason: Reason, event: E): ChangeEventDetails<Reason, E> {
  let canceled = false;
  return {
    cancel: () => {
      canceled = true;
    },
    event,
    get isCanceled() {
      return canceled;
    },
    reason,
  };
}

/**
 * One pointer at a time on a control: while one drags, a press from another is
 * ignored, and the same pointer pressing again means its release was missed,
 * so the drag it left ends there. Moves arrive at most once per frame, each
 * with where the pointer was at the last one.
 */
export function createPointerLock() {
  type Held = {
    end: (event: PointerEvent) => void;
    pointerId: number;
    stop: () => void;
  };
  let held: Held | null = null;
  return {
    claim: (event: PointerEvent) => {
      if (!held) {
        return true;
      }
      if (held.pointerId !== event.pointerId) {
        return false;
      }
      const stale = held;
      held = null;
      stale.stop();
      stale.end(event);
      return true;
    },
    follow: (
      target: Element,
      down: PointerEvent,
      move: (event: PointerEvent, from: { x: number; y: number }) => void,
      end: (event: PointerEvent) => void
    ) => {
      let last = { x: down.clientX, y: down.clientY };
      const entry: Held = {
        end,
        pointerId: down.pointerId,
        stop: () => undefined,
      };
      held = entry;
      entry.stop = bindDrag(target as HTMLElement, down, {
        onEnd: (event) => {
          if (held === entry) {
            held = null;
          }
          end(event);
        },
        onMove: ({ event }) => {
          const from = last;
          last = { x: event.clientX, y: event.clientY };
          move(event, from);
        },
      });
    },
  };
}

/**
 * A value that changes outside the framework, in the shape of an external
 * store: `subscribe` registers a listener called on each change, and
 * `getSnapshot` returns the current value. What a primitive's `source` reads
 * from, so that following a signal costs no render.
 */
export interface Source<Value> {
  getSnapshot: () => Value;
  subscribe: (listener: () => void) => () => void;
}

/** A value the primitive holds and its parts read outside any render. */
export interface Store<Value> {
  get: () => Value;
  set: (next: Value) => void;
  subscribe: (listener: () => void) => () => void;
}

/** A store holding `initial`: `set` tells every listener, unless the value is the same one. */
export function createStore<Value>(initial: Value): Store<Value> {
  let value = initial;
  const listeners = new Set<() => void>();
  return {
    get: () => value,
    set: (next) => {
      if (Object.is(next, value)) {
        return;
      }
      value = next;
      for (const listener of listeners) {
        listener();
      }
    },
    subscribe: (listener) => {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
  };
}

/** What a gesture hears, from the press that started it to its release. */
export interface GestureHandlers<Data> {
  /** The pointer lifted, or the browser took it over (`canceled`). */
  onEnd: (event: PointerEvent, data: Data, canceled: boolean) => void;
  /** At most once per frame, with the latest pointer event. */
  onMove: (event: PointerEvent, data: Data, sample: PointerSample) => void;
}

/**
 * A primitive's pointer gestures, one at a time. Call `accepts` first, before
 * the primitive's own guards: another pointer pressing while a gesture runs
 * is refused, so a second finger does not take the gesture over, and the
 * same pointer pressing again means its release was missed, so its gesture
 * ends there, through `onStale`. A gesture carries `data` of its own, read
 * back by `active`, and stops when the primitive is destroyed.
 */
export function createGestures<Data>(context: {
  onDestroy: (cleanup: () => void) => void;
}) {
  type Running = { data: Data; pointerId: number; stop: () => void };
  let running: Running | null = null;
  context.onDestroy(() => running?.stop());
  return {
    /** Whether `event` may start a gesture, ending a stale one of the same pointer first. */
    accepts(event: PointerEvent, onStale?: (data: Data) => void) {
      const stale = running;
      if (!stale) {
        return true;
      }
      if (stale.pointerId !== event.pointerId) {
        return false;
      }
      running = null;
      stale.stop();
      onStale?.(stale.data);
      return true;
    },
    /** The data of the gesture that runs, if any. */
    active: () => running?.data ?? null,
    /** Follows the press on `el` until it lifts. */
    start(
      el: HTMLElement,
      event: PointerEvent,
      data: Data,
      handlers: GestureHandlers<Data>
    ) {
      running?.stop();
      const entry: Running = {
        data,
        pointerId: event.pointerId,
        stop: () => undefined,
      };
      running = entry;
      entry.stop = bindDrag(el, event, {
        onEnd: (end, canceled) => {
          if (running === entry) {
            running = null;
          }
          handlers.onEnd(end, data, canceled);
        },
        onMove: (sample) => handlers.onMove(sample.event, data, sample),
      });
    },
  };
}

const KEBAB = /([a-z0-9])([A-Z])/g;
const kebab = (name: string) => name.replace(KEBAB, "$1-$2").toLowerCase();

/**
 * The part a primitive draws names itself in `data-slot`, in kebab case
 * (`xypad-input-x`, `piano-roll-note`), the names the styles and the docs
 * select: the kernel writes the slot's key as it is (`xypad-inputX`). A
 * component that gives its own name to a part (`timeline-time-selection`)
 * keeps it.
 */
function nameSlots(name: string, slots: Record<string, any>) {
  const prefix = kebab(name);
  for (const [key, definition] of Object.entries(slots)) {
    const fallback = key === "root" ? prefix : `${prefix}-${kebab(key)}`;
    const { attrs } = definition;
    definition.attrs = (state: unknown, context: { props?: object }) => ({
      ...attrs?.(state, context),
      "data-slot":
        (context.props as Record<string, string> | undefined)?.["data-slot"] ??
        fallback,
    });
    definition.props = { ...definition.props, "data-slot": "string" };
  }
  return slots;
}

/** `definePrimitive` of the kernel, with the parts named in kebab case and a `data-slot` that can be given. */
export const definePrimitive = ((options: any) =>
  definePrimitiveOf({
    ...options,
    slots: (slot: unknown) => nameSlots(options.name, options.slots(slot)),
  })) as typeof definePrimitiveOf;

import {
  css,
  dispatch,
  type PrimitiveInstance,
  type PropSpec,
  type SlotDefinition,
} from "@ui-sdk/core";
import { clamp } from "@ui-sdk/core/number";
import {
  moveRange,
  normalizeRange,
  type RangeEdge,
  type RangeValue,
} from "../grid";
import {
  type ChangeDetails,
  type CommitDetails,
  createGestures,
  createReporter,
  createStore,
  definePrimitive,
  flag,
  type Source,
  type Store,
  sourceOf,
  VISUALLY_HIDDEN,
} from "../primitive";
import { isAudible } from "./levels";
import type { WaveformIdle } from "./levels-engine";
import { attachWaveformBars } from "./paint-bars";
import { attachWaveformCanvas } from "./paint-canvas";
import type { WaveformPeaks } from "./peaks";

export type { ChangeDetails, CommitDetails } from "../primitive";
export type { WaveformIdle } from "./levels-engine";
export type { WaveformPeaks } from "./peaks";

/**
 * The waveform: a position to seek, a stretch of the audio shown, regions to
 * move and resize, and the canvas and the bars painted outside any render.
 * The press, the scrub, the keys, the Shift + drag selection and the regions
 * are the primitive's own (`waveform.ts`); the painters are beside it.
 *
 * The position reaches the DOM in one place, the Root's `bind`: the
 * `--waveform-position` CSS variable the playhead and thumb follow, the store
 * the painters read, and the input assistive technology reads. A live `source`
 * therefore paints every frame with no render.
 *
 * A region is named, by its `region` prop, and holds a value of its own.
 * What it reports goes through the Root, `onRegionChange` and
 * `onRegionCommitted`, with the region's name and the edge in the details.
 */

/** What a change to a region moves: its start, its end, or the whole region with `"both"`. */
export type WaveformRegionEdge = RangeEdge;
/** A region as `[start, end]`, in `duration` units. */
export type WaveformRegionValue = RangeValue;

const noop = () => undefined;

const POSITION_PROPERTY = "--waveform-position";
const LEVEL_PROPERTY = "--waveform-level";

/** A share of the track is meaningful whatever unit `duration` is in. */
const describeAsPercent = (value: number, duration: number) =>
  `${Math.round((duration > 0 ? value / duration : 0) * 100)}%`;

export type DescribeValue = (value: number, duration: number) => string;

/** A live position, in `duration` units. */
export type PositionSource = Source<number>;

/** A live signal: the current levels, 0…1 each. */
export type LevelsSource = Source<ArrayLike<number>>;

export interface WaveformPrimitiveOptions {
  defaultValue?: number;
  disabled?: boolean;
  /** Length of the audio, in the unit `value` is in. @default 1 */
  duration?: number;
  /** Step for Page Up/Page Down and Shift + arrow keys. Defaults to a tenth of `duration`. */
  largeStep?: number;
  /** A live signal drawn outside any render, instead of `peaks`. */
  levels?: LevelsSource;
  /** Whether the audio is still on its way. @default false */
  loading?: boolean;
  /** The form field's name. */
  name?: string;
  /** A Shift + drag moved the selection: `[start, end]`, with `details.cancel()` to keep it. */
  onRegionChange?: (
    value: WaveformRegionValue,
    details: RegionChangeDetails
  ) => void;
  onRegionCommitted?: (
    value: WaveformRegionValue,
    details: RegionCommitDetails
  ) => void;
  onSelectionChange?: (
    range: readonly [number, number],
    details: ChangeDetails
  ) => void;
  onSelectionCommitted?: (
    range: readonly [number, number],
    details: CommitDetails
  ) => void;
  onValueChange?: (value: number, details: ChangeDetails) => void;
  onValueCommitted?: (value: number, details: CommitDetails) => void;
  /** The audio's shape: a level per slice, or `{ min, max }` samples per slice. */
  peaks?: WaveformPeaks;
  /** The stretch of the audio shown, `[start, end]` in `duration` units. */
  range?: readonly [number, number];
  /** A live position followed outside any render; takes precedence over `value`. */
  source?: PositionSource;
  /** Step for the arrow keys. Defaults to a hundredth of `duration`. */
  step?: number;
  value?: number;
}

/** What a region's change reports. */
export interface RegionChangeDetails extends ChangeDetails {
  edge: WaveformRegionEdge;
  /** The name of the region that moved. */
  region: string;
}

/** What a region's commit reports. */
export interface RegionCommitDetails extends CommitDetails {
  edge: WaveformRegionEdge;
  region: string;
}

export interface WaveformState {
  disabled: boolean;
  /** Where a drag has taken the position, held until release so a controlled position that lags cannot pull the waveform back. */
  draft: number | null;
  /** Whether a pointer is scrubbing or selecting. */
  dragging: boolean;
  duration: number;
  largeStep: number;
  levels: LevelsSource | undefined;
  loading: boolean;
  name: string | undefined;
  peaks: WaveformPeaks | undefined;
  /** The stretch of the audio shown, `[start, end]` in `duration` units. */
  range: readonly [number, number];
  /** Counts the changes a region made, so the parts read them again. */
  regions: number;
  /** The live position the waveform follows, when it has one. */
  source: PositionSource | undefined;
  step: number;
  /** The position the app holds, or the waveform's own. */
  value: number;
}

/** What a view draws a waveform from. */
export interface WaveformView {
  disabled: boolean;
  dragging: boolean;
  duration: number;
  largeStep: number;
  loading: boolean;
  range: readonly [number, number];
  step: number;
  /** The position as displayed: the dragged one while a pointer moves it, or the live source's. */
  value: number;
}

/** What a part reads of the waveform. */
export interface WaveformPublicState {
  disabled: boolean;
  /** Whether a pointer is scrubbing the waveform. */
  dragging: boolean;
  /** Whether the audio is still on its way: there is nothing to seek yet. */
  loading: boolean;
}

/** What a region's parts read of it. */
export interface RegionPublicState extends WaveformPublicState {
  /** The region, as `[start, end]`. */
  value: WaveformRegionValue;
}

/** What a bar reads of itself. */
export interface BarPublicState extends WaveformPublicState {
  index: number;
}

/** The props every part takes. */
interface PartProps {
  id?: string;
}

/** The props of a region part: its name, and what it holds. */
export interface RegionProps extends PartProps {
  defaultValue?: WaveformRegionValue;
  disabled?: boolean;
  minLength?: number;
  movable?: boolean;
  /** The name of the region: what keys it and what its changes report. */
  region: string;
  value?: WaveformRegionValue;
}

/** What a region reads, and every way of moving it. */
export interface RegionHandle {
  /** How far an edge can go: the limits of its position, which stop short of the other edge. */
  edgeRange: (edge: WaveformRegionEdge) => readonly [number, number];
  getSnapshot: () => RegionView;
  /** Handles a key on an edge's input: arrows and Page keys move it, Home and End go to its ends. Returns whether the edge took the key. */
  keyDown: (edge: WaveformRegionEdge, event: KeyboardEvent) => boolean;
  /** Starts a drag of `edge` (or of the whole region, `"both"`) from `handle`; `track` is the element the region sits on, which turns pixels into `duration` units. */
  press: (
    edge: WaveformRegionEdge,
    event: PointerEvent,
    handle: HTMLElement,
    track: Element | null
  ) => void;
  /** Moves an edge to a position from an input. */
  typeAt: (edge: WaveformRegionEdge, position: number, event: Event) => void;
}

/** What a view draws a region from. */
export interface RegionView {
  disabled: boolean;
  dragging: boolean;
  duration: number;
  largeStep: number;
  minLength: number;
  step: number;
  /** The region as displayed: the dragged one while a pointer moves it. */
  value: WaveformRegionValue;
}

/** What a waveform's `api` gives an adapter. */
export interface WaveformApi {
  /** The nodes of the bars, by index, which the bars painter writes to. */
  bars: { minLevel: number; nodes: Map<number, HTMLElement> };
  /** How the position is announced; set by the input. */
  describe: { current: DescribeValue };
  /** The position under the pointer while it hovers, in `duration` units, or null. */
  hover: Store<number | null>;
  /** Sets the hover from a pointer over `element`. */
  hoverAt: (clientX: number, element: Element) => void;
  /** Which key a `"key"` prop is keyed by. */
  internal: { keyOf: (value: unknown) => string };
  /** Handles a key on the seekable surface's input. Returns whether the seek took the key. */
  keyDown: (event: KeyboardEvent) => boolean;
  /** The pointer left the surface: the hover goes. */
  leave: () => void;
  /** The played share, 0 to 1, observable outside any render. */
  position: Store<number>;
  /** Starts a press on `element`: a press seeks, a drag scrubs; with Shift held and a selection listener, a drag selects a stretch instead. */
  pressSeek: (event: PointerEvent, element: HTMLElement) => void;
  /** The region named in `props`, with the latest props when they are the region part's own. */
  regionFor: (
    props: RegionProps | RegionPartProps,
    /** Whether `props` are the region part's own, which hold what the region is given. */
    owner?: boolean
  ) => RegionHandle;
  /** Sets the position from an input, reporting an `"input-change"` change and commit. */
  typeAt: (value: number, event: Event) => void;
}

/** The props of a region's edge parts. */
export interface RegionPartProps extends PartProps {
  getAriaValueText?: DescribeValue;
  region: string;
}

/** The painters' props, which a part passes through. */
export interface CanvasProps extends PartProps {
  barGap?: number;
  barRadius?: number;
  barWidth?: number;
  gain?: number;
  idle?: WaveformIdle;
  lineWidth?: number;
  minBarHeight?: number;
  mirrored?: boolean;
  mode?: "scrolling" | "static";
  scrollSpeed?: number;
  variant?: "bars" | "line" | "mirror" | "scope";
}

export interface BarsProps extends PartProps {
  count?: number;
  gain?: number;
  idle?: WaveformIdle;
  minLevel?: number;
  mirrored?: boolean;
}

type Slot<Props, Public = WaveformPublicState> = SlotDefinition<
  WaveformState,
  WaveformApi,
  Props,
  Public
>;

/** The waveform's slots, by name, with the props and the public state of each. */
export type WaveformSlots = {
  bar: Slot<PartProps & { index: number }, BarPublicState>;
  bars: Slot<BarsProps>;
  canvas: Slot<CanvasProps>;
  control: Slot<PartProps>;
  hover: Slot<PartProps & { format?: (value: number) => string }>;
  input: Slot<PartProps & { getAriaValueText?: DescribeValue }, object>;
  marker: Slot<PartProps & { value: number }>;
  playhead: Slot<PartProps>;
  region: Slot<RegionProps, RegionPublicState>;
  regionEnd: Slot<RegionPartProps, RegionPublicState>;
  regionEndInput: Slot<RegionPartProps, object>;
  regionStart: Slot<RegionPartProps, RegionPublicState>;
  regionStartInput: Slot<RegionPartProps, object>;
  root: Slot<PartProps>;
  thumb: Slot<PartProps>;
};

/** The type of `waveform`, written out so a declaration can print it. */
export interface WaveformPrimitive {
  options: Record<string, PropSpec> | undefined;
  slots: WaveformSlots;
  (
    initialOptions: WaveformPrimitiveOptions & { id: string }
  ): Omit<PrimitiveInstance, "api" | "get" | "types"> & {
    api: WaveformApi;
    get: () => WaveformState;
    types: {
      api: WaveformApi;
      options: WaveformPrimitiveOptions;
      slots: WaveformSlots;
      state: WaveformState;
    };
  };
}

/** The position the waveform shows: the dragged one, or the live source's, or the held one. */
const positionOf = (state: WaveformState) =>
  state.draft ??
  clampFinite(
    state.source ? state.source.getSnapshot() : state.value,
    0,
    state.duration
  );

/** `value` within `min` and `max`, or `min` when it is not a number. */
const clampFinite = (value: number, min: number, max: number) =>
  Number.isFinite(value) ? clamp(value, min, max) : min;

const views = new WeakMap<WaveformState, WaveformView>();

/** What the parts draw from `state`, worked out once per state. */
export function viewOf(state: WaveformState): WaveformView {
  const cached = views.get(state);
  if (cached) {
    return cached;
  }
  const view: WaveformView = {
    disabled: state.disabled,
    dragging: state.dragging,
    duration: state.duration,
    largeStep: state.largeStep,
    loading: state.loading,
    range: state.range,
    step: state.step,
    value: positionOf(state),
  };
  views.set(state, view);
  return view;
}

/** How far across the shown stretch `value` is: 0 at its start, 1 at its end. */
function shareOf(state: WaveformState, value: number) {
  const [start, end] = state.range;
  return end > start ? (value - start) / (end - start) : 0;
}

/** The value at `share` of the way across the shown stretch. */
function atShare(state: WaveformState, share: number) {
  const [start, end] = state.range;
  return start + share * (end - start);
}

/** The state an options object asks for, with the defaults of the waveform. */
function stateOf(options: WaveformPrimitiveOptions) {
  const duration = options.duration ?? 1;
  const [start, end] = options.range
    ? normalizeRange(options.range, duration)
    : [0, duration];
  return {
    disabled: options.disabled ?? false,
    duration,
    largeStep: options.largeStep ?? duration / 10,
    levels: options.levels,
    loading: options.loading ?? false,
    name: options.name,
    peaks: options.peaks,
    range: end > start ? ([start, end] as const) : ([0, duration] as const),
    source: options.source,
    step: options.step ?? duration / 100,
  };
}

const publicState = (state: WaveformState): WaveformPublicState => ({
  disabled: state.disabled,
  dragging: state.dragging,
  loading: state.loading,
});

const stateAttrs = (state: WaveformState) => ({
  "data-disabled": flag(state.disabled),
  "data-dragging": flag(state.dragging),
  "data-loading": flag(state.loading),
});

const percentOf = (share: number) =>
  `${Math.min(1, Math.max(0, share)) * 100}%`;

/** The element a region's pixels are measured on: the track it is positioned in. */
const trackOf = (region: Element | null): Element | null =>
  region
    ? ((region as HTMLElement).offsetParent ?? region.parentElement)
    : null;

const reducedMotion = () =>
  typeof matchMedia === "function" &&
  matchMedia("(prefers-reduced-motion: reduce)").matches;

/**
 * Runs `attach` again whenever what it draws from changes: the root's state, a
 * part's props (written as `data-paint`), or the part's element.
 */
function repaint(
  el: HTMLElement,
  store: Store<WaveformState>,
  signature: () => unknown[],
  attach: () => () => void
) {
  let last: unknown[] = [];
  let detach: () => void = noop;
  const run = () => {
    const next = signature();
    if (
      next.length === last.length &&
      next.every((value, index) => Object.is(value, last[index]))
    ) {
      return;
    }
    last = next;
    detach();
    detach = attach();
  };
  run();
  const off = store.subscribe(run);
  const observer = new MutationObserver(run);
  observer.observe(el, { attributeFilter: ["data-paint"], attributes: true });
  return () => {
    off();
    observer.disconnect();
    detach();
    last = [];
  };
}

const paintSignature = (props: object) =>
  JSON.stringify(props, (_key, value) =>
    typeof value === "function" ? undefined : value
  );

/** One pointer gesture on the waveform: a seek, or a Shift + drag selection. */
interface SeekGesture {
  /** Where a selection began. */
  anchor: number;
  /** Whether it moved the position, or selected a stretch, at least once; if so its end commits. */
  changed: boolean;
  kind: "seek" | "select";
  /** Whether the pointer moved after the press: the commit reason is "drag", else "press". */
  moved: boolean;
  /** The stretch selected so far. */
  selected: readonly [number, number] | null;
}

/** One drag of a region or of one of its edges. */
interface RegionGesture {
  changed: boolean;
  edge: WaveformRegionEdge;
  /** The region when the pointer went down: the drag is measured from it. */
  origin: WaveformRegionValue;
  startX: number;
  /** The last region the drag applied, which its end commits. */
  value: WaveformRegionValue | null;
}

/** What the waveform keeps of one region. */
interface RegionRecord {
  dragging: boolean;
  gestures: ReturnType<typeof createGestures<RegionGesture>>;
  handle: RegionHandle;
  /** The region as the gesture under way left it: a controlled region that lags behind must not pull it back mid-drag. */
  latest: WaveformRegionValue | null;
  /** The props of the region part's newest render. */
  props: RegionProps;
  snapshot: RegionView | null;
  /** Held by the region, unless its `value` is given. */
  uncontrolled: WaveformRegionValue | undefined;
}

export const waveform: WaveformPrimitive = definePrimitive({
  agent: { actions: ["setValue"] },
  api: (context) => {
    const { commit, report, setAtOnce, state } = createReporter(
      context,
      positionOf,
      Object.is
    );
    const set = (next: Partial<WaveformState>) =>
      context.store.set(next as never);
    const options = () => context.options() as WaveformPrimitiveOptions;
    const gestures = createGestures<SeekGesture>(context);
    const hover = createStore<number | null>(null);
    const position = createStore(shareOf(state(), positionOf(state())));
    const inert = () => state().disabled || state().loading;
    const toDuration = (value: number) =>
      clampFinite(value, 0, state().duration);
    const valueAt = (element: Element, clientX: number) => {
      const rect = element.getBoundingClientRect();
      return atShare(
        state(),
        clamp((clientX - rect.left) / Math.max(rect.width, 1), 0, 1)
      );
    };

    /** Proposes a position during a gesture; keeps it unless refused, and says whether it was applied. */
    const moveTo = (raw: number, reason: string, event: Event) => {
      const next = toDuration(raw);
      if (next === positionOf(state()) || !report(next, reason, event)) {
        return false;
      }
      set({ draft: next });
      return true;
    };

    /** Ends a gesture, committing what it changed. */
    const finish = (gesture: SeekGesture, end: PointerEvent) => {
      if (gesture.kind === "seek") {
        // Read before settling: the position falls back to the known value after.
        const committed = positionOf(state());
        set({ dragging: false, draft: null });
        if (gesture.changed) {
          commit(committed, gesture.moved ? "drag" : "press", end);
        }
        return;
      }
      set({ dragging: false });
      if (gesture.changed && gesture.selected) {
        dispatch(context, "onSelectionCommitted", gesture.selected, {
          event: end,
          reason: "drag",
        });
      }
    };

    // ---- regions

    const records = new Map<string, RegionRecord>();
    const bump = () => set({ regions: state().regions + 1 });

    const createRecord = (name: string, props: RegionProps) => {
      const record: RegionRecord = {
        dragging: false,
        gestures: createGestures<RegionGesture>(context),
        handle: undefined as unknown as RegionHandle,
        latest: null,
        props,
        snapshot: null,
        uncontrolled: undefined,
      };
      const limits = () => ({
        duration: state().duration,
        minLength: record.props.minLength ?? state().step,
      });
      const disabled = () => state().disabled || Boolean(record.props.disabled);
      const held = (): WaveformRegionValue =>
        normalizeRange(
          record.props.value ??
            record.uncontrolled ??
            record.props.defaultValue ?? [0, state().duration],
          state().duration
        );
      const current = () => record.latest ?? held();

      /** Proposes a region; keeps it unless refused. Returns the region applied, or null. */
      const change = (
        next: WaveformRegionValue,
        edge: WaveformRegionEdge,
        reason: string,
        event: Event
      ) => {
        const [start, end] = current();
        if (next[0] === start && next[1] === end) {
          return null;
        }
        const source = sourceOf(event);
        const canceled = dispatch(context, "onRegionChange", next, {
          edge,
          event,
          reason,
          region: name,
          ...(source ? { source } : {}),
        });
        if (canceled) {
          return null;
        }
        record.latest = next;
        if (record.props.value === undefined) {
          record.uncontrolled = next;
        }
        bump();
        return next;
      };
      // A commit reports the region just applied: the region may have been
      // drawn again, from props that lag, before it is made.
      const commitRegion = (
        value: WaveformRegionValue,
        edge: WaveformRegionEdge,
        reason: string,
        event: Event
      ) =>
        dispatch(context, "onRegionCommitted", value, {
          edge,
          event,
          reason,
          region: name,
        });
      const settle = (
        next: WaveformRegionValue,
        edge: WaveformRegionEdge,
        reason: string,
        event: Event
      ) => {
        const applied = change(next, edge, reason, event);
        if (applied) {
          commitRegion(applied, edge, reason, event);
        }
      };

      /** The region with `edge` moved to `position`, measured from the region as it is now, within its limits. */
      const withEdgeAt = (edge: WaveformRegionEdge, target: number) => {
        const now = current();
        return moveRange(
          now,
          edge,
          target - (edge === "start" ? now[0] : now[1]),
          limits()
        );
      };
      const edgeRange = (edge: WaveformRegionEdge) => {
        const [start, end] = current();
        const { duration } = state();
        const { minLength } = limits();
        return edge === "start"
          ? ([0, Math.max(0, end - minLength)] as const)
          : ([Math.min(duration, start + minLength), duration] as const);
      };
      const finishRegion = (gesture: RegionGesture, end: PointerEvent) => {
        record.dragging = false;
        record.latest = null;
        bump();
        if (gesture.changed && gesture.value) {
          commitRegion(gesture.value, gesture.edge, "drag", end);
        }
      };

      record.handle = {
        edgeRange,
        getSnapshot: () => {
          const now = state();
          const next: RegionView = {
            disabled: disabled(),
            dragging: record.dragging,
            duration: now.duration,
            largeStep: now.largeStep,
            minLength: limits().minLength,
            step: now.step,
            value: record.dragging && record.latest ? record.latest : held(),
          };
          const known = record.snapshot;
          if (
            known &&
            known.value[0] === next.value[0] &&
            known.value[1] === next.value[1] &&
            known.disabled === next.disabled &&
            known.dragging === next.dragging &&
            known.duration === next.duration &&
            known.largeStep === next.largeStep &&
            known.minLength === next.minLength &&
            known.step === next.step
          ) {
            return known;
          }
          record.snapshot = next;
          return next;
        },
        keyDown: (edge, event) => {
          if (disabled()) {
            return false;
          }
          const [min, max] = edgeRange(edge);
          const now = current();
          const at = edge === "start" ? now[0] : now[1];
          const { largeStep, step } = state();
          const arrowStep = event.shiftKey ? largeStep : step;
          const target = {
            ArrowDown: at - arrowStep,
            ArrowLeft: at - arrowStep,
            ArrowRight: at + arrowStep,
            ArrowUp: at + arrowStep,
            End: max,
            Home: min,
            PageDown: at - largeStep,
            PageUp: at + largeStep,
          }[event.key];
          if (target === undefined) {
            return false;
          }
          settle(withEdgeAt(edge, target), edge, "keyboard", event);
          return true;
        },
        press: (edge, event, handle, track) => {
          if (
            disabled() ||
            event.button !== 0 ||
            !record.gestures.accepts(event, (stale) =>
              finishRegion(stale, event)
            )
          ) {
            return;
          }
          const gesture: RegionGesture = {
            changed: false,
            edge,
            origin: current(),
            startX: event.clientX,
            value: null,
          };
          record.dragging = true;
          bump();
          // Pixels become `duration` units by the stretch shown, over the track it sits on.
          const unitsPerPixel = () => {
            const width = track?.getBoundingClientRect().width ?? 0;
            const [from, to] = state().range;
            return (to - from) / Math.max(width, 1);
          };
          record.gestures.start(handle, event, gesture, {
            onEnd: (end) => finishRegion(gesture, end),
            onMove: (move) => {
              const delta = (move.clientX - gesture.startX) * unitsPerPixel();
              const applied = change(
                moveRange(gesture.origin, edge, delta, limits()),
                edge,
                "drag",
                move
              );
              if (applied) {
                gesture.changed = true;
                gesture.value = applied;
              }
            },
          });
        },
        typeAt: (edge, at, event) => {
          if (!state().disabled) {
            settle(withEdgeAt(edge, at), edge, "input-change", event);
          }
        },
      };
      return record;
    };

    return {
      bars: { minLevel: 0.08, nodes: new Map<number, HTMLElement>() },
      describe: { current: describeAsPercent },
      hover,
      hoverAt: (clientX: number, element: Element) => {
        if (!inert()) {
          hover.set(valueAt(element, clientX));
        }
      },
      internal: { keyOf: (value: unknown) => String(value) },
      keyDown: (event: KeyboardEvent) => {
        if (inert()) {
          return false;
        }
        const now = positionOf(state());
        const [start, end] = state().range;
        const { largeStep, step } = state();
        const arrowStep = event.shiftKey ? largeStep : step;
        const target = {
          ArrowDown: now - arrowStep,
          ArrowLeft: now - arrowStep,
          ArrowRight: now + arrowStep,
          ArrowUp: now + arrowStep,
          End: end,
          Home: start,
          PageDown: now - largeStep,
          PageUp: now + largeStep,
        }[event.key];
        if (target === undefined) {
          return false;
        }
        // The keys move within the stretch shown.
        setAtOnce(toDuration(clamp(target, start, end)), "keyboard", event);
        return true;
      },
      leave: () => hover.set(null),
      position,
      pressSeek: (event: PointerEvent, element: HTMLElement) => {
        if (
          inert() ||
          event.button !== 0 ||
          !gestures.accepts(event, (stale) => finish(stale, event))
        ) {
          return;
        }
        const gesture: SeekGesture = {
          anchor: 0,
          changed: false,
          kind: "seek",
          moved: false,
          selected: null,
        };
        // Shift selects a stretch, as in an audio editor, when the app listens for it; a plain press seeks.
        if (event.shiftKey && options().onSelectionChange) {
          gesture.kind = "select";
          gesture.anchor = valueAt(element, event.clientX);
          set({ dragging: true });
          gestures.start(element, event, gesture, {
            onEnd: (end) => finish(gesture, end),
            onMove: (move) => {
              const at = valueAt(element, move.clientX);
              const range = [
                Math.min(gesture.anchor, at),
                Math.max(gesture.anchor, at),
              ] as const;
              const canceled = dispatch(context, "onSelectionChange", range, {
                event: move,
                reason: "drag",
              });
              if (!canceled) {
                gesture.changed = true;
                gesture.selected = range;
              }
            },
          });
          return;
        }
        set({ dragging: true });
        gesture.changed = moveTo(
          valueAt(element, event.clientX),
          "press",
          event
        );
        gestures.start(element, event, gesture, {
          onEnd: (end) => finish(gesture, end),
          onMove: (move) => {
            gesture.moved = true;
            if (moveTo(valueAt(element, move.clientX), "drag", move)) {
              gesture.changed = true;
            }
          },
        });
      },
      regionFor: (props: RegionProps | RegionPartProps, owner = false) => {
        const name = String(props.region);
        let record = records.get(name);
        if (!record) {
          record = createRecord(name, props as RegionProps);
          records.set(name, record);
        } else if (owner) {
          // The region is told the props of its newest render.
          record.props = props as RegionProps;
          if (!record.dragging) {
            record.latest = null;
          }
        }
        return record.handle;
      },
      typeAt: (value: number, event: Event) => {
        if (!inert()) {
          setAtOnce(toDuration(value), "input-change", event);
        }
      },
    };
  },
  controlled: ["value"],
  name: "waveform",
  options: {
    defaultValue: "number",
    disabled: "boolean",
    duration: "number",
    largeStep: "number",
    levels: "value",
    loading: "boolean",
    name: "string",
    onRegionChange: "callback",
    onRegionCommitted: "callback",
    onSelectionChange: "callback",
    onSelectionCommitted: "callback",
    onValueChange: "callback",
    onValueCommitted: "callback",
    peaks: "value",
    range: "value",
    source: "value",
    step: "number",
    value: "number",
  },
  slots: (slot) => {
    /** A part that follows the region named in its props. */
    const regionState = (api: WaveformApi, props: object) =>
      api.regionFor(props as RegionProps).getSnapshot();

    const edgeSlot = (edge: "end" | "start") =>
      slot<RegionPartProps, RegionPublicState>({
        attrs: (_state: WaveformState, { api, props }) => {
          const view = regionState(api, props);
          return {
            "data-disabled": flag(view.disabled),
            "data-dragging": flag(view.dragging),
            "data-edge": edge,
            "data-region": String(props.region),
            style: css({ "touch-action": "none" }),
          };
        },
        on: {
          pointerdown: (event, { api, el, props }) => {
            if (event.button !== 0) {
              return;
            }
            // The press stops here, so the control underneath takes no seek.
            event.stopPropagation();
            const handle = api.regionFor(props);
            if (!el || handle.getSnapshot().disabled) {
              return;
            }
            event.preventDefault();
            el.querySelector<HTMLInputElement>('input[type="range"]')?.focus({
              preventScroll: true,
            });
            const regionEl = el.closest<HTMLElement>(
              '[data-slot="waveform-region"]'
            );
            handle.press(edge, event, el, trackOf(regionEl));
          },
        },
        props: { getAriaValueText: "value", region: "key" },
        state: (state: WaveformState, { api, props }) => ({
          ...publicState(state),
          value: regionState(api, props).value,
        }),
      });

    const edgeInputSlot = (edge: "end" | "start") =>
      slot<RegionPartProps>({
        attrs: (state: WaveformState, { api, props }) => {
          const handle = api.regionFor(props);
          const view = handle.getSnapshot();
          const current = edge === "start" ? view.value[0] : view.value[1];
          const [min, max] = handle.edgeRange(edge);
          return {
            "aria-valuetext": (props.getAriaValueText ?? describeAsPercent)(
              current,
              state.duration
            ),
            disabled: flag(view.disabled),
            max: String(max),
            min: String(min),
            step: "any",
            style: css(VISUALLY_HIDDEN),
            type: "range",
            value: String(current),
          };
        },
        on: {
          change: (event, { api, el, props }) =>
            api
              .regionFor(props)
              .typeAt(edge, Number((el as HTMLInputElement).value), event),
          keydown: (event, { api, props }) => {
            if (api.regionFor(props).keyDown(edge, event)) {
              event.preventDefault();
            }
          },
        },
        props: { getAriaValueText: "value", region: "key" },
      });

    return {
      bar: slot<{ index: number }, BarPublicState>({
        attrs: (_state: WaveformState, { api, props }) => ({
          "data-index": String(props.index),
          style: css({ [LEVEL_PROPERTY]: String(api.bars.minLevel) }),
        }),
        bind: (el, part) => {
          const index = Number(part.props.index);
          part.api.bars.nodes.set(index, el);
          return () => {
            if (part.api.bars.nodes.get(index) === el) {
              part.api.bars.nodes.delete(index);
            }
          };
        },
        props: { index: "key" },
        state: (state: WaveformState, { props }) => ({
          ...publicState(state),
          index: Number(props.index),
        }),
      }),
      bars: slot<BarsProps, WaveformPublicState>({
        attrs: (state: WaveformState, { api, props }) => {
          api.bars.minLevel = props.minLevel ?? 0.08;
          return {
            ...stateAttrs(state),
            "data-paint": paintSignature(props),
          };
        },
        bind: (el, part) =>
          repaint(
            el,
            part.store,
            () => {
              const state = part.store.get();
              return [
                paintSignature(part.props),
                state.duration,
                state.levels,
                state.loading,
                state.peaks,
                state.range[0],
                state.range[1],
              ];
            },
            () => {
              const state = part.store.get();
              const { count = 24, gain, idle, minLevel, mirrored } = part.props;
              return attachWaveformBars(
                el,
                (index) => part.api.bars.nodes.get(index),
                {
                  count,
                  duration: state.duration,
                  gain,
                  idle,
                  levels: state.levels,
                  loading: state.loading,
                  minLevel,
                  mirrored,
                  peaks: state.peaks,
                  played: part.api.position,
                  range: state.range,
                  reducedMotion: reducedMotion(),
                }
              );
            }
          ),
        props: {
          count: "number",
          gain: "number",
          idle: "string",
          minLevel: "number",
          mirrored: "boolean",
        },
        state: (state: WaveformState) => publicState(state),
      }),
      canvas: slot<CanvasProps, WaveformPublicState>({
        attrs: (state: WaveformState, { props }) => ({
          ...stateAttrs(state),
          "aria-hidden": "true",
          "data-paint": paintSignature(props),
        }),
        bind: (el, part) =>
          repaint(
            el,
            part.store,
            () => {
              const state = part.store.get();
              return [
                paintSignature(part.props),
                state.duration,
                state.levels,
                state.loading,
                state.peaks,
                state.range[0],
                state.range[1],
              ];
            },
            () => {
              const state = part.store.get();
              return attachWaveformCanvas(el as HTMLCanvasElement, {
                ...part.props,
                duration: state.duration,
                levels: state.levels,
                loading: state.loading,
                peaks: state.peaks,
                played: part.api.position,
                range: state.range,
                reducedMotion: reducedMotion(),
              });
            }
          ),
        props: {
          barGap: "number",
          barRadius: "number",
          barWidth: "number",
          gain: "number",
          idle: "string",
          lineWidth: "number",
          minBarHeight: "number",
          mirrored: "boolean",
          mode: "string",
          scrollSpeed: "number",
          variant: "string",
        },
        state: (state: WaveformState) => publicState(state),
      }),
      control: slot<object, WaveformPublicState>({
        attrs: (state: WaveformState) => ({
          ...stateAttrs(state),
          style: css({ position: "relative", "touch-action": "none" }),
        }),
        on: {
          pointerdown: (event, { api, el, store }) => {
            const now = store.get();
            if (!el || now.disabled || now.loading || event.button !== 0) {
              return;
            }
            event.preventDefault();
            el.querySelector<HTMLInputElement>('input[type="range"]')?.focus({
              preventScroll: true,
            });
            api.pressSeek(event, el);
          },
          pointerleave: (_event, { api }) => api.leave(),
          pointermove: (event, { api, el, store }) => {
            if (!el || store.get().disabled || store.get().loading) {
              return;
            }
            api.hoverAt(event.clientX, el);
          },
        },
        state: (state: WaveformState) => publicState(state),
      }),
      // Shown while the pointer is over the control, at the hovered point.
      hover: slot<{ format?: (value: number) => string }, WaveformPublicState>({
        attrs: (state: WaveformState) => ({
          ...stateAttrs(state),
          "aria-hidden": "true",
          hidden: "",
          style: css({ position: "absolute" }),
        }),
        bind: (el, part) => {
          const text = document.createTextNode("");
          el.appendChild(text);
          const paint = () => {
            const hovered = part.api.hover.get();
            const state = part.store.get();
            const shown =
              hovered !== null && !(state.disabled || state.loading);
            el.toggleAttribute("hidden", !shown);
            if (!shown) {
              return;
            }
            el.style.left = percentOf(shareOf(state, hovered));
            const next = part.props.format?.(hovered) ?? "";
            if (text.nodeValue !== next) {
              text.nodeValue = next;
            }
          };
          paint();
          const off = part.api.hover.subscribe(paint);
          return () => {
            off();
            text.remove();
          };
        },
        props: { format: "value" },
        state: (state: WaveformState) => publicState(state),
      }),
      input: slot<{ getAriaValueText?: DescribeValue }>({
        attrs: (state: WaveformState, { api, props }) => {
          // Kept current for the paints that happen outside any render.
          api.describe.current = props.getAriaValueText ?? describeAsPercent;
          return {
            "aria-valuetext": api.describe.current(
              viewOf(state).value,
              state.duration
            ),
            disabled: flag(state.disabled),
            max: String(state.range[1]),
            min: String(state.range[0]),
            name: state.name,
            step: "any",
            style: css(VISUALLY_HIDDEN),
            type: "range",
            value: String(viewOf(state).value),
          };
        },
        on: {
          change: (event, { api, el }) =>
            api.typeAt(Number((el as HTMLInputElement).value), event),
          keydown: (event, { api }) => {
            if (api.keyDown(event)) {
              event.preventDefault();
            }
          },
        },
        props: { getAriaValueText: "value" },
      }),
      marker: slot<{ value: number }, WaveformPublicState>({
        attrs: (state: WaveformState, { props }) => ({
          ...stateAttrs(state),
          style: css({
            left: percentOf(
              shareOf(
                state,
                clampFinite(Number(props.value), 0, state.duration)
              )
            ),
            position: "absolute",
          }),
        }),
        props: { value: "number" },
        state: (state: WaveformState) => publicState(state),
      }),
      playhead: slot<object, WaveformPublicState>({
        attrs: (state: WaveformState) => ({
          ...stateAttrs(state),
          "aria-hidden": "true",
          style: css({
            left: `var(${POSITION_PROPERTY})`,
            position: "absolute",
          }),
        }),
        state: (state: WaveformState) => publicState(state),
      }),
      region: slot<RegionProps, RegionPublicState>({
        attrs: (state: WaveformState, { api, props }) => {
          const view = api.regionFor(props as RegionProps, true).getSnapshot();
          const [from, to] = state.range;
          const span = to - from;
          const share = (length: number) =>
            `${(span > 0 ? length / span : 0) * 100}%`;
          return {
            "data-disabled": flag(view.disabled),
            "data-dragging": flag(view.dragging),
            "data-region": String(props.region),
            style: css({
              left: share(view.value[0] - from),
              position: "absolute",
              "touch-action": "none",
              width: share(view.value[1] - view.value[0]),
            }),
          };
        },
        on: {
          pointerdown: (event, { api, el, props }) => {
            if (event.button !== 0) {
              return;
            }
            event.stopPropagation();
            const handle = api.regionFor(props, true);
            if (
              !el ||
              props.movable === false ||
              handle.getSnapshot().disabled
            ) {
              return;
            }
            event.preventDefault();
            handle.press("both", event, el, trackOf(el));
          },
        },
        props: {
          defaultValue: "value",
          disabled: "boolean",
          minLength: "number",
          movable: "boolean",
          region: "key",
          value: "value",
        },
        state: (state: WaveformState, { api, props }) => ({
          ...publicState(state),
          value: regionState(api, props).value,
        }),
      }),
      regionEnd: edgeSlot("end"),
      regionEndInput: edgeInputSlot("end"),
      regionStart: edgeSlot("start"),
      regionStartInput: edgeInputSlot("start"),
      root: slot<object, WaveformPublicState>({
        attrs: (state: WaveformState) => ({
          ...stateAttrs(state),
          style: css({
            [POSITION_PROPERTY]: percentOf(shareOf(state, viewOf(state).value)),
          }),
        }),
        // The single place a position reaches the DOM, outside any render.
        bind: (el, part) => {
          const { position } = part.api;
          const paint = () => {
            const now = part.store.get();
            const { duration } = now;
            const next = clampFinite(positionOf(now), 0, duration);
            const share = shareOf(now, next);
            el.style.setProperty(POSITION_PROPERTY, percentOf(share));
            // Outside the stretch shown, a playhead has nowhere true to stand.
            el.toggleAttribute("data-outside", share < 0 || share > 1);
            position.set(share);
            const input = el.querySelector<HTMLInputElement>(
              '[data-slot="waveform-input"]'
            );
            if (input) {
              const text = part.api.describe.current(next, duration);
              if (input.getAttribute("aria-valuetext") !== text) {
                input.setAttribute("aria-valuetext", text);
                input.value = String(next);
              }
            }
          };
          let followed: PositionSource | undefined;
          let unfollow: () => void = noop;
          let heard: LevelsSource | undefined;
          let unhear: () => void = noop;
          const mark = () => {
            const { levels } = part.store.get();
            el.toggleAttribute(
              "data-active",
              levels ? isAudible(levels.getSnapshot()) : false
            );
          };
          const watch = () => {
            const live = part.store.get().source;
            if (live !== followed) {
              unfollow();
              followed = live;
              unfollow = live ? live.subscribe(paint) : () => undefined;
            }
            const { levels } = part.store.get();
            if (levels !== heard) {
              unhear();
              heard = levels;
              unhear = levels ? levels.subscribe(mark) : () => undefined;
            }
            mark();
            paint();
          };
          watch();
          const offStore = part.store.subscribe(watch);
          return () => {
            offStore();
            unfollow();
            unhear();
            el.removeAttribute("data-active");
          };
        },
        state: (state: WaveformState) => publicState(state),
      }),
      thumb: slot<object, WaveformPublicState>({
        attrs: (state: WaveformState) => ({
          ...stateAttrs(state),
          "aria-hidden": "true",
          style: css({
            left: `var(${POSITION_PROPERTY})`,
            position: "absolute",
            // Centering stays in `transform`, so `translate` remains free for styling.
            transform: "translateX(-50%)",
          }),
        }),
        state: (state: WaveformState) => publicState(state),
      }),
    };
  },
  state: (options: WaveformPrimitiveOptions): WaveformState => ({
    ...stateOf(options),
    draft: null,
    dragging: false,
    regions: 0,
    value: options.value ?? options.defaultValue ?? 0,
  }),
  sync: (options: WaveformPrimitiveOptions) => ({
    ...stateOf(options),
    ...(options.value === undefined ? {} : { value: options.value }),
  }),
});

/**
 * Painting outside any render: a task that runs on animation frames only
 * while it has something to animate, and a watch on whether an element is in
 * view. Shared by the waveform and the timeline.
 */

/** The longest step the clock takes, so a task that slept or sat in a hidden tab never jumps ahead. */
const MAX_STEP_MS = 100;

/** What `createFrameTask` returns: wake it when something moves, flush it to step at once, stop it for good. */
export interface FrameTask {
  /** Run a step now, without waiting for the pending frame. */
  flush: () => void;
  /** Stop for good: a stopped task ignores `wake` and `flush`. */
  stop: () => void;
  /** Run a step on the next animation frame, unless one is already pending. */
  wake: () => void;
}

/**
 * Runs `step` on animation frames for as long as it returns true, and sleeps
 * otherwise: a painter with nothing left to animate costs no frames until it
 * is woken. `step` receives the time since the previous step, in milliseconds:
 * zero on the first step after a sleep, and never more than 100.
 */
export function createFrameTask(
  step: (elapsedMs: number) => boolean
): FrameTask {
  let frame = 0;
  let lastMs: number | null = null;
  let stopped = false;

  const wake = () => {
    if (!stopped && frame === 0) {
      frame = requestAnimationFrame(run);
    }
  };

  function run(nowMs: number) {
    frame = 0;
    const elapsed =
      lastMs === null ? 0 : Math.min(Math.max(0, nowMs - lastMs), MAX_STEP_MS);
    lastMs = nowMs;
    if (step(elapsed)) {
      wake();
    } else {
      lastMs = null;
    }
  }

  return {
    flush: () => {
      if (stopped) {
        return;
      }
      cancelAnimationFrame(frame);
      run(performance.now());
    },
    stop: () => {
      stopped = true;
      cancelAnimationFrame(frame);
      frame = 0;
    },
    wake,
  };
}

/**
 * Calls `onChange` when `element` enters or leaves the viewport, so a painter
 * can skip frames nobody sees. Returns a function that stops observing.
 */
export function observeVisibility(
  element: Element,
  onChange: (visible: boolean) => void
): () => void {
  if (typeof IntersectionObserver === "undefined") {
    return () => undefined;
  }
  const observer = new IntersectionObserver((entries) => {
    const entry = entries.at(-1);
    if (entry) {
      onChange(entry.isIntersecting);
    }
  });
  observer.observe(element);
  return () => observer.disconnect();
}

/**
 * The grid the timeline and the piano roll snap to, and the ranges they move:
 * shared by both, beside `primitive.ts`.
 */

import { clamp } from "@ui-sdk/core/number";

/** `value` within `min` and `max`, or `min` when it is not a number. */
const clampFinite = (value: number, min: number, max: number) =>
  Number.isFinite(value) ? clamp(value, min, max) : min;

/** A stretch of a timeline, `[start, end]` in its units. */
export type RangeValue = readonly [start: number, end: number];

/** What a change moves: one edge, or the whole range with `both`. */
export type RangeEdge = "both" | "end" | "start";

/** What a range is kept within: the timeline's length and the shortest it may be. */
export interface RangeLimits {
  duration: number;
  /** The shortest a range may be resized to. */
  minLength: number;
}

/** Orders a range's edges and keeps them on the timeline. */
export function normalizeRange(
  value: RangeValue,
  duration: number
): RangeValue {
  const first = clampFinite(value[0], 0, duration);
  const second = clampFinite(value[1], 0, duration);
  return first <= second ? [first, second] : [second, first];
}

/**
 * Moves one edge of `origin` by `delta`, or the whole range, without leaving
 * the timeline. An edge stops `minLength` short of the other one; a range
 * moved as a whole keeps its length.
 */
export function moveRange(
  origin: RangeValue,
  edge: RangeEdge,
  delta: number,
  limits: RangeLimits
): RangeValue {
  const [start, end] = origin;
  const { duration, minLength } = limits;
  if (edge === "both") {
    const length = end - start;
    const next = clamp(start + delta, 0, Math.max(0, duration - length));
    return [next, next + length];
  }
  if (edge === "start") {
    return [clamp(start + delta, 0, Math.max(0, end - minLength)), end];
  }
  return [
    start,
    clamp(end + delta, Math.min(duration, start + minLength), duration),
  ];
}

/**
 * Grid lines `step` apart, starting from `offset`. A `step` of 0 or less is no
 * grid. `points` are places that pull harder than the lines, such as the
 * edges of other clips and the locators: within `radius` of one, a dragged
 * thing lands on it. The radius is set per gesture from how many units a few
 * pixels are.
 */
export interface Grid {
  offset: number;
  points?: readonly number[];
  radius?: number;
  step: number;
}

/** How far from a snap point, in px, a dragged thing is pulled onto it. */
export const SNAP_RADIUS_PX = 8;

/** The grid with its points pulling from `radius` units away, so a gesture can set it from its own zoom. */
export function withSnapRadius(grid: Grid, radius: number): Grid {
  return grid.points?.length ? { ...grid, radius } : grid;
}

/** The point of `grid` nearest `value` within its radius, or null when none is that close. */
export function nearestSnapPoint(value: number, grid: Grid): number | null {
  const radius = grid.radius ?? 0;
  let found: number | null = null;
  for (const point of grid.points ?? []) {
    const distance = Math.abs(point - value);
    if (
      distance <= radius &&
      (found === null || distance < Math.abs(found - value))
    ) {
      found = point;
    }
  }
  return found;
}

/** Whether a gesture asks to ignore the grid: Cmd on a Mac, Ctrl elsewhere. */
export function bypassesGrid(event: {
  ctrlKey?: boolean;
  metaKey?: boolean;
}): boolean {
  return Boolean(event.metaKey || event.ctrlKey);
}

/** The snap point within reach of `value`, or else the grid line nearest it. */
export function snapToGrid(value: number, grid: Grid): number {
  const point = nearestSnapPoint(value, grid);
  if (point !== null) {
    return point;
  }
  if (!(grid.step > 0)) {
    return value;
  }
  return (
    Math.round((value - grid.offset) / grid.step) * grid.step + grid.offset
  );
}

/**
 * Where something dragged from `origin` should land, given where the pointer
 * would put it. A snap point within reach wins. Otherwise two answers are
 * reasonable, and the one nearer the pointer wins: on a grid line, or moved
 * by a whole number of steps from where it was. Without the second, anything that starts between two lines jumps onto
 * one the moment it is touched, and can never move by exactly one step.
 */
export function snapMove(target: number, origin: number, grid: Grid): number {
  const point = nearestSnapPoint(target, grid);
  if (point !== null) {
    return point;
  }
  if (!(grid.step > 0)) {
    return target;
  }
  const onLine = snapToGrid(target, grid);
  const bySteps =
    origin + Math.round((target - origin) / grid.step) * grid.step;
  return Math.abs(onLine - target) <= Math.abs(bySteps - target)
    ? onLine
    : bySteps;
}

/**
 * Where a span `length` long, dragged from `origin`, should start when the
 * pointer would start it at `target`: either of its edges lands on a snap
 * point within reach (the nearer one wins), or else its start snaps the way
 * anything dragged does.
 */
export function snapSpanMove(
  target: number,
  origin: number,
  length: number,
  grid: Grid
): number {
  const startPoint = nearestSnapPoint(target, grid);
  const endPoint = nearestSnapPoint(target + length, grid);
  if (startPoint !== null || endPoint !== null) {
    if (endPoint === null) {
      return startPoint ?? target;
    }
    if (
      startPoint === null ||
      Math.abs(endPoint - (target + length)) < Math.abs(startPoint - target)
    ) {
      return endPoint - length;
    }
    return startPoint;
  }
  return snapMove(target, origin, { ...grid, points: undefined });
}

/** The grid without the given points, so something dragged is not pulled onto its own edges. */
export function withoutSnapPoints(grid: Grid, own: readonly number[]): Grid {
  return grid.points?.length
    ? { ...grid, points: grid.points.filter((point) => !own.includes(point)) }
    : grid;
}

/**
 * Where one edge of a range dragged from `origin`, or the whole range with
 * `"both"`, should land when the pointer has moved it by `delta`: the
 * dragged edge snaps the way anything dragged does, and the range keeps
 * within the timeline and its minimum length.
 */
export function snapRangeMove(
  origin: RangeValue,
  edge: RangeEdge,
  delta: number,
  limits: RangeLimits,
  grid: Grid
): RangeValue {
  if (edge === "both") {
    const length = origin[1] - origin[0];
    return moveRange(
      origin,
      edge,
      snapSpanMove(origin[0] + delta, origin[0], length, grid) - origin[0],
      limits
    );
  }
  const from = edge === "end" ? origin[1] : origin[0];
  return moveRange(
    origin,
    edge,
    snapMove(from + delta, from, grid) - from,
    limits
  );
}

/**
 * `bars` stands the bars on the baseline, `mirror` centers them on the middle
 * line, and `line` joins the levels into one continuous, centered shape.
 * `scope` is for raw samples rather than levels: it traces them, -1…1, as a
 * single line through the middle, like an oscilloscope.
 */
export type WaveformVariant = "bars" | "line" | "mirror" | "scope";

import type { PeakEnvelope } from "./peaks";

/** Where the bars go on the canvas bitmap. Every length is in device pixels. */
export interface BarLayout {
  barWidth: number;
  count: number;
  height: number;
  minBarHeight: number;
  /** Distance between the left edges of two neighbouring bars. */
  pitch: number;
  variant: WaveformVariant;
  width: number;
}

/** What `barLayout` lays bars out for: the canvas's size and pixel ratio, the bars' width, gap and shortest height, and the variant. */
export interface BarLayoutOptions {
  /** Space between bars, in CSS pixels. */
  barGap: number;
  /** Bar width, in CSS pixels. */
  barWidth: number;
  /** Bitmap height, in device pixels. */
  height: number;
  /** Shortest bar, in CSS pixels: silence still draws a sliver, so the timeline stays readable. */
  minBarHeight: number;
  /** Device pixels per CSS pixel. */
  pixelRatio: number;
  variant: WaveformVariant;
  /** Bitmap width, in device pixels. */
  width: number;
}

/** A bar's rectangle on the bitmap, in whole device pixels. */
export interface BarRect {
  height: number;
  width: number;
  x: number;
  y: number;
}

/**
 * How many device pixels a CSS length covers on the canvas bitmap. The
 * browser's own count is exact where a layout box doesn't land on a whole
 * pixel, so it wins when it agrees with the pixel ratio. It doesn't under
 * device emulation, which reports the real screen's pixels.
 */
export function bitmapLength(
  cssLength: number,
  pixelRatio: number,
  exact?: number
): number {
  const estimate = Math.round(cssLength * pixelRatio);
  return exact !== undefined && Math.abs(exact - estimate) <= 1
    ? exact
    : estimate;
}

/** How many bars of `barWidth` separated by `barGap` fit in `width`. */
export function barCount(
  width: number,
  barWidth: number,
  barGap: number
): number {
  if (width <= 0 || barWidth <= 0) {
    return 0;
  }
  return Math.max(1, Math.floor((width + barGap) / (barWidth + barGap)));
}

/** A CSS length in whole device pixels: at least one, so nothing thin disappears. */
function snap(length: number, pixelRatio: number): number {
  return length > 0 ? Math.max(1, Math.round(length * pixelRatio)) : 0;
}

/**
 * Lay the bars out on the device pixel grid. Widths and gaps given in CSS
 * pixels become whole device pixels, so every bar is the same width and no
 * edge falls between two pixels, whatever the pixel density or zoom level.
 */
export function barLayout(options: BarLayoutOptions): BarLayout {
  const { height, pixelRatio, variant, width } = options;
  const barWidth = snap(options.barWidth, pixelRatio);
  const barGap = snap(options.barGap, pixelRatio);
  return {
    barWidth,
    count: barCount(width, barWidth, barGap),
    height,
    minBarHeight: snap(options.minBarHeight, pixelRatio),
    pitch: barWidth + barGap,
    variant,
    width,
  };
}

/**
 * Where bar `index` goes for a level of 0…1, in whole device pixels. `bars`
 * stands it on the baseline; the other variants center it. `shift` moves the
 * whole row, for a waveform that scrolls.
 */
export function barRect(
  level: number,
  index: number,
  layout: BarLayout,
  shift = 0
): BarRect {
  const { barWidth, height, minBarHeight, pitch, variant } = layout;
  const barHeight = Math.min(
    height,
    Math.max(minBarHeight, Math.round(level * height))
  );
  return {
    height: barHeight,
    width: barWidth,
    x: index * pitch + shift,
    y:
      variant === "bars"
        ? height - barHeight
        : Math.round((height - barHeight) / 2),
  };
}

/**
 * How far to shift a row of `count` bars so the last one sits flush with the
 * right edge once it has fully slid in. `progress` is how far it has, 0…1; the
 * slide moves in whole device pixels, so bars stay sharp while they scroll.
 */
export function scrollShift(
  count: number,
  progress: number,
  layout: BarLayout
): number {
  const { barWidth, pitch, width } = layout;
  const settled = width - barWidth - (count - 1) * pitch;
  return settled + Math.round((1 - Math.min(1, Math.max(0, progress))) * pitch);
}

/** Where each level goes, left to right. `shift` moves the whole row. */
export function barRects(
  levels: ArrayLike<number>,
  layout: BarLayout,
  shift = 0
): BarRect[] {
  return Array.from(levels, (level, index) =>
    barRect(level, index, layout, shift)
  );
}

/**
 * Where each level of a history goes when it scrolls outwards from the
 * middle, left to right: the newest stays in the center, growing out of the
 * one before it, while older ones slide away on both sides. `progress` is how
 * far the newest has come in, 0…1.
 */
export function mirroredScrollRects(
  levels: ArrayLike<number>,
  progress: number,
  layout: BarLayout
): BarRect[] {
  const last = levels.length - 1;
  if (last < 0) {
    return [];
  }
  const { barWidth, pitch, width } = layout;
  const center = Math.round((width - barWidth) / 2);
  const slide = Math.min(1, Math.max(0, progress));
  const newest = levels[last] ?? 0;
  const previous = levels[last - 1] ?? newest;
  const left: BarRect[] = [];
  const right: BarRect[] = [];
  for (let age = 1; age <= last; age += 1) {
    const distance = Math.round((age - 1 + slide) * pitch);
    if (distance > center + barWidth) {
      break;
    }
    const level = levels[last - age] ?? 0;
    left.unshift(barRect(level, 0, layout, center - distance));
    right.push(barRect(level, 0, layout, center + distance));
  }
  const middle = barRect(
    previous + (newest - previous) * slide,
    0,
    layout,
    center
  );
  return [...left, middle, ...right];
}

/**
 * Where each bar of an envelope goes, in whole device pixels: from its high
 * to its low around the middle, never thinner than the shortest bar. `bars`
 * stands each one on the baseline instead, as tall as it reaches either way.
 */
export function envelopeRects(
  envelope: PeakEnvelope,
  layout: BarLayout
): BarRect[] {
  const { barWidth, height, minBarHeight, pitch, variant } = layout;
  const middle = height / 2;
  return Array.from(envelope.high, (high, index) => {
    const low = envelope.low[index] ?? 0;
    if (variant === "bars") {
      return barRect(Math.max(high, -low), index, layout);
    }
    let top = Math.round(middle - high * middle);
    let bottom = Math.round(middle - low * middle);
    if (bottom - top < minBarHeight) {
      top = Math.round((top + bottom - minBarHeight) / 2);
      bottom = top + minBarHeight;
    }
    return { height: bottom - top, width: barWidth, x: index * pitch, y: top };
  });
}

/** Without a reading for this long, the signal has stopped and so does the scroll. */
const MIN_STALL_MS = 250;

/** What `createLevelHistory` returns: feed it levels, step it every frame, and read the window it scrolls and how far the newest entry has slid in. */
export interface LevelHistory {
  /** Give the current level, read at `nowMs`. The loudest one given since the last entry is what gets recorded. */
  feed: (level: number, nowMs: number) => void;
  /** The recorded levels, oldest first. The last one is the entry sliding in. */
  readonly levels: Float32Array;
  /** How far the newest entry has slid in, 0…1. */
  readonly progress: number;
  /** Bring the history up to `nowMs`. Returns `true` while it is still moving. */
  step: (nowMs: number) => boolean;
}

/**
 * Records a level every `intervalMs` into a window of `size` entries that
 * scrolls: each new entry pushes the oldest one out. Time only passes while
 * levels keep coming: when the signal stops the history holds still, and when
 * it comes back it carries on from there, the gap left out. `previous` brings
 * the newest entries of an earlier history over, so a resize doesn't wipe
 * what was recorded.
 */
export function createLevelHistory(
  size: number,
  intervalMs: number,
  previous?: Float32Array
): LevelHistory {
  const levels = new Float32Array(Math.max(1, Math.floor(size)));
  if (previous) {
    const kept = previous.subarray(
      Math.max(0, previous.length - levels.length)
    );
    levels.set(kept, levels.length - kept.length);
  }
  const interval = Math.max(1, intervalMs);
  const stallMs = Math.max(MIN_STALL_MS, interval * 4);
  /** The time the history has been brought up to. */
  let advancedTo: number | null = null;
  /** When the last level was given. */
  let fedAt = Number.NEGATIVE_INFINITY;
  /** Time since the newest entry was recorded. */
  let sinceEntry = 0;
  /** The last level given; held when nothing new arrives before the next entry. */
  let latest = 0;
  /** The loudest level given since the newest entry. */
  let pending = 0;

  return {
    feed: (level, nowMs) => {
      if (nowMs - fedAt > stallMs) {
        // Back after a silence: time picks up from here.
        advancedTo = nowMs;
      }
      fedAt = nowMs;
      latest = level;
      pending = Math.max(pending, level);
    },
    levels,
    get progress() {
      return sinceEntry / interval;
    },
    step: (nowMs) => {
      if (nowMs - fedAt > stallMs) {
        return false;
      }
      sinceEntry += Math.max(0, nowMs - (advancedTo ?? nowMs));
      advancedTo = nowMs;
      while (sinceEntry >= interval) {
        levels.copyWithin(0, 1);
        levels[levels.length - 1] = pending;
        pending = latest;
        sinceEntry -= interval;
      }
      return true;
    },
  };
}

import { clampUnit, fitPeaks, loudest, SILENCE_THRESHOLD } from "./levels";

/** Time constant of the fall after a peak, in milliseconds: levels rise at once and fall smoothly. */
const RELEASE_MS = 110;
/** A level this close to its target has nothing left to animate. */
const SETTLE_EPSILON = 0.002;

const PULSE_PERIOD_MS = 1250;
const PULSE_LEVEL = 0.1;
const WAVE_PERIOD_MS = 1500;
const WAVE_LEVEL = 0.16;
/** How many bars one cycle of the idle wave spans. */
const WAVE_LENGTH = 12;
const SWEEP_PERIOD_MS = 1200;
const SWEEP_LEVEL = 0.55;

/**
 * What the bars do while there is no signal: `none` rests them, `pulse` makes
 * them breathe together and `wave` runs a ripple along them.
 */
export type WaveformIdle = "none" | "pulse" | "wave";

/** What a levels engine fits its input to: the bar count, the gain, the shortest level, whether the bars mirror, and what they do while idle, loading or with reduced motion. */
export interface LevelsEngineOptions {
  count: number;
  /** Visual gain applied to the input. */
  gain: number;
  idle: WaveformIdle;
  /** Runs a sweep across the bars, for a connecting or decoding state. */
  loading: boolean;
  /** Resting level, 0…1. */
  minLevel: number;
  /** Mirrors the levels around the middle bar: the first level sits in the center. */
  mirrored: boolean;
  /** No release smoothing, idle animation or sweep. */
  reducedMotion: boolean;
}

/** What `createLevelsEngine` returns: step it every frame with the input, and read the levels and whether they have settled. */
export interface LevelsEngine {
  /** The level each bar shows, 0…1, never below `minLevel`. */
  readonly levels: Float32Array;
  /** Whether the last step left nothing to animate. */
  readonly settled: boolean;
  /** Advance to `nowMs` (a clock in milliseconds) with the latest input. */
  step: (nowMs: number, input: ArrayLike<number> | null | undefined) => void;
}

function idleLevel(idle: WaveformIdle, index: number, nowMs: number): number {
  if (idle === "pulse") {
    const phase = (nowMs / PULSE_PERIOD_MS) * Math.PI * 2;
    return PULSE_LEVEL * (0.5 - 0.5 * Math.cos(phase));
  }
  if (idle === "wave") {
    const phase = (nowMs / WAVE_PERIOD_MS - index / WAVE_LENGTH) * Math.PI * 2;
    return WAVE_LEVEL * (0.5 + 0.5 * Math.sin(phase));
  }
  return 0;
}

/** A bump that crosses the bars once per period, entering and leaving off the edges. */
function sweepLevel(index: number, count: number, nowMs: number): number {
  const spread = Math.max(1.5, count * 0.06);
  const margin = spread * 3;
  const cycle = (nowMs % SWEEP_PERIOD_MS) / SWEEP_PERIOD_MS;
  const center = cycle * (count + margin * 2) - margin;
  return SWEEP_LEVEL * Math.exp(-((index - center) ** 2) / (2 * spread ** 2));
}

/**
 * Turns an input of any length into the level of each of `count` bars: fitted
 * to the bar count, rising at once and falling smoothly, optionally mirrored,
 * with an idle animation while silent and a sweep while loading.
 */
export function createLevelsEngine(options: LevelsEngineOptions): LevelsEngine {
  const { gain, idle, loading, minLevel, mirrored, reducedMotion } = options;
  const count = Math.max(0, Math.floor(options.count));
  const half = mirrored ? Math.ceil(count / 2) : count;
  const targets = new Float32Array(half);
  const current = new Float32Array(count);
  const levels = new Float32Array(count).fill(clampUnit(minLevel));
  let lastMs: number | null = null;
  let settled = false;

  const sweeping = loading && !reducedMotion;
  const canIdle = idle !== "none" && !reducedMotion;

  /** Which fitted level bar `index` shows: mirrored, the distance from the middle. */
  const targetIndex = (index: number) =>
    mirrored
      ? Math.min(half - 1, Math.floor(Math.abs(index - (count - 1) / 2)))
      : index;

  /** What an animation adds to bar `index`: the loading sweep, or the idle motion while quiet. */
  const animated = (index: number, nowMs: number, quiet: boolean) => {
    if (sweeping) {
      return sweepLevel(index, count, nowMs);
    }
    return quiet && canIdle ? idleLevel(idle, index, nowMs) : 0;
  };

  const step: LevelsEngine["step"] = (nowMs, input) => {
    const elapsed = lastMs === null ? 0 : Math.max(0, nowMs - lastMs);
    lastMs = nowMs;
    const keep = reducedMotion ? 0 : Math.exp(-elapsed / RELEASE_MS);
    fitPeaks(input ?? [], targets);
    const quiet = loudest(targets) * gain < SILENCE_THRESHOLD;
    let converged = true;

    for (let index = 0; index < count; index += 1) {
      const target = Math.max(
        clampUnit((targets[targetIndex(index)] ?? 0) * gain),
        animated(index, nowMs, quiet)
      );
      const previous = current[index] ?? 0;
      const next =
        target >= previous ? target : target + (previous - target) * keep;
      current[index] = next;
      levels[index] = clampUnit(Math.max(minLevel, next));
      converged &&= Math.abs(next - target) <= SETTLE_EPSILON;
    }
    settled = converged && !(sweeping || (quiet && canIdle));
  };

  return {
    levels,
    get settled() {
      return settled;
    },
    step,
  };
}

/** `value` kept within 0 and 1. */
export const clampUnit = (value: number) => Math.max(0.0, Math.min(value, 1.0));

/** Loudest level under which a signal counts as silence. */
export const SILENCE_THRESHOLD = 0.02;

/** The loudest magnitude in `levels`. */
export function loudest(levels: ArrayLike<number>): number {
  let max = 0;
  // biome-ignore lint/style/useForOf: an ArrayLike is not iterable
  for (let index = 0; index < levels.length; index += 1) {
    max = Math.max(max, Math.abs(levels[index] ?? 0));
  }
  return max;
}

/** Whether `levels` carry a signal, rather than silence. */
export function isAudible(levels: ArrayLike<number>): boolean {
  return loudest(levels) >= SILENCE_THRESHOLD;
}

const magnitude = (peaks: ArrayLike<number>, index: number): number =>
  Math.min(1, Math.abs(peaks[index] ?? 0));

/** More peaks than bars: each bar keeps the loudest peak in its slice of the data. */
function reducePeaks(peaks: ArrayLike<number>, levels: Float32Array) {
  const { length } = peaks;
  for (let bar = 0; bar < levels.length; bar += 1) {
    const start = Math.floor((bar * length) / levels.length);
    const end = Math.max(
      start + 1,
      Math.floor(((bar + 1) * length) / levels.length)
    );
    let peak = 0;
    for (let i = start; i < end && i < length; i += 1) {
      peak = Math.max(peak, magnitude(peaks, i));
    }
    levels[bar] = peak;
  }
}

/** Fewer peaks than bars: each bar blends its two nearest peaks, aligned on their centers. */
function stretchPeaks(peaks: ArrayLike<number>, levels: Float32Array) {
  const last = peaks.length - 1;
  for (let bar = 0; bar < levels.length; bar += 1) {
    const at = Math.min(
      last,
      Math.max(0, ((bar + 0.5) * peaks.length) / levels.length - 0.5)
    );
    const before = Math.floor(at);
    const from = magnitude(peaks, before);
    const to = magnitude(peaks, Math.min(last, before + 1));
    levels[bar] = from + (to - from) * (at - before);
  }
}

/**
 * Fit `peaks` to `levels`, one level per bar. With more peaks than bars, each
 * bar takes the loudest peak in its slice, so a short transient never
 * disappears between bars; with fewer, neighbouring peaks are blended so the
 * shape stays smooth instead of stepping. Returns `levels`.
 */
export function fitPeaks(
  peaks: ArrayLike<number>,
  levels: Float32Array
): Float32Array {
  if (peaks.length === 0) {
    levels.fill(0);
  } else if (peaks.length < levels.length) {
    stretchPeaks(peaks, levels);
  } else {
    reducePeaks(peaks, levels);
  }
  return levels;
}

import { createFrameTask, observeVisibility } from "../frame";
import type { Source } from "../primitive";
import { createLevelsEngine, type WaveformIdle } from "./levels-engine";
import {
  peakCount,
  peakMagnitudes,
  rangeShares,
  type WaveformPeaks,
} from "./peaks";

const LEVEL_PROPERTY = "--waveform-level";
/** A level has to move this much before its bar is written to again. */
const PAINT_EPSILON = 0.002;
/** With reduced motion, the bars repaint this often at most. */
const REDUCED_MOTION_INTERVAL_MS = 250;

/** The played share of the audio, 0…1, as it changes. */
export interface WaveformPlayed {
  get: () => number;
  subscribe: (listener: () => void) => () => void;
}

/** The options of `attachWaveformBars`: the bar count, the peaks or a live signal, the stretch shown and the played share, and how the bars move. */
export interface WaveformBarsOptions {
  /** How many bars there are. */
  count: number;
  /** Length of the audio, in the unit `range` is in. */
  duration: number;
  /** Visual gain applied to the levels before they are drawn. @default 1 */
  gain?: number;
  /** What the bars do while there is no signal. @default "none" */
  idle?: WaveformIdle;
  /** A live signal, 0…1 per level, followed instead of `peaks`. */
  levels?: Source<ArrayLike<number>>;
  /** Whether the audio is still on its way: the bars sweep. */
  loading?: boolean;
  /** Resting level, 0…1. @default 0.08 */
  minLevel?: number;
  /** Mirrors the levels around the middle bar, the first one in the center. */
  mirrored?: boolean;
  /** The audio's shape, when it is known upfront. */
  peaks?: WaveformPeaks;
  /** The played share, which marks the bars it has passed `data-played`. */
  played: WaveformPlayed;
  /** The stretch of the audio shown, `[start, end]` in `duration` units. */
  range: readonly [number, number];
  /** Whether motion is reduced: the bars repaint four times a second at most. */
  reducedMotion?: boolean;
}

/**
 * Draws a waveform as `count` elements, `bar(index)` each: writes each
 * one's level, 0…1, to its `--waveform-level` CSS variable, rising at once
 * and falling smoothly, and nothing while they rest or `root` is off screen.
 * Bars the played share has passed get `data-played`. Returns what stops it.
 */
export function attachWaveformBars(
  root: Element,
  bar: (index: number) => HTMLElement | null | undefined,
  options: WaveformBarsOptions
): () => void {
  const { count, duration, levels: live, peaks, played, range } = options;
  const reducedMotion = options.reducedMotion ?? false;
  const engine = createLevelsEngine({
    count,
    gain: options.gain ?? 1,
    idle: options.idle ?? "none",
    loading: options.loading ?? false,
    minLevel: options.minLevel ?? 0.08,
    mirrored: options.mirrored ?? false,
    reducedMotion,
  });
  const shown = new Float32Array(engine.levels.length).fill(-1);
  let input: ArrayLike<number> | undefined;
  if (live) {
    input = live.getSnapshot();
  } else if (peaks) {
    // The shown stretch at the data's own resolution: the engine fits it to the bars.
    const [from, to] = rangeShares(range, duration);
    const entries = Math.max(1, Math.round((to - from) * peakCount(peaks)));
    input = peakMagnitudes(peaks, from, to, entries);
  }
  let visible = true;
  let clock = 0;
  let unpaintedMs = 0;
  let sincePaintMs = Number.POSITIVE_INFINITY;
  const task = createFrameTask((elapsedMs) => {
    if (!visible) {
      return false;
    }
    unpaintedMs += elapsedMs;
    sincePaintMs += elapsedMs;
    if (reducedMotion && sincePaintMs < REDUCED_MOTION_INTERVAL_MS) {
      return true;
    }
    clock += unpaintedMs;
    unpaintedMs = 0;
    sincePaintMs = 0;
    engine.step(clock, input);
    for (const [index, level] of engine.levels.entries()) {
      if (Math.abs(level - (shown[index] ?? -1)) > PAINT_EPSILON) {
        shown[index] = level;
        bar(index)?.style.setProperty(LEVEL_PROPERTY, level.toFixed(4));
      }
    }
    return !engine.settled;
  });
  const markPlayed = () => {
    const share = played.get();
    for (let index = 0; index < count; index += 1) {
      bar(index)?.toggleAttribute(
        "data-played",
        (index + 0.5) / count <= share
      );
    }
  };
  task.flush();
  markPlayed();
  const stopObservingVisibility = observeVisibility(root, (next) => {
    visible = next;
    if (next) {
      task.wake();
    }
  });
  const unsubscribePlayed = played.subscribe(markPlayed);
  const unsubscribeLevels = live?.subscribe(() => {
    input = live.getSnapshot();
    task.wake();
  });
  return () => {
    task.stop();
    stopObservingVisibility();
    unsubscribePlayed();
    unsubscribeLevels?.();
  };
}

import { createFrameTask, observeVisibility } from "../frame";
import type { Source } from "../primitive";
import {
  type BarLayout,
  type BarRect,
  barLayout,
  barRects,
  bitmapLength,
  envelopeRects,
  mirroredScrollRects,
  scrollShift,
  type WaveformVariant,
} from "./bar-layout";
import { createLevelHistory, type LevelHistory } from "./level-history";
import { clampUnit, loudest } from "./levels";
import {
  createLevelsEngine,
  type LevelsEngine,
  type WaveformIdle,
} from "./levels-engine";
import type { WaveformPlayed } from "./paint-bars";
import {
  fitPeaks,
  type PeakEnvelope,
  rangeShares,
  type WaveformPeaks,
} from "./peaks";
import { type ScopePoint, scopePoints } from "./scope";

const BAR_RADIUS_PROPERTY = "--waveform-bar-radius";
const THEME_ATTRIBUTES = ["class", "style", "data-theme"];
/** With reduced motion, a moving waveform repaints this often at most. */
const REDUCED_MOTION_INTERVAL_MS = 250;
const MS_PER_SECOND = 1000;
/**
 * Browsers refuse canvases much larger than this on a side, and a refused
 * canvas draws nothing. Past it the bitmap is drawn coarser instead: a
 * zoomed-in clip blurs a little rather than going blank.
 */
const MAX_BITMAP_SIDE = 16_384;

let barRadiusPropertyRegistered = false;

/**
 * Registers the bar radius as a CSS length, so a themed value such as
 * `min(var(--radius-sm), 3px)` computes to pixels the canvas can draw with.
 */
function registerBarRadiusProperty() {
  if (barRadiusPropertyRegistered) {
    return;
  }
  barRadiusPropertyRegistered = true;
  if (typeof CSS === "undefined" || !("registerProperty" in CSS)) {
    return;
  }
  try {
    CSS.registerProperty({
      inherits: true,
      initialValue: "0px",
      name: BAR_RADIUS_PROPERTY,
      syntax: "<length>",
    });
  } catch {
    // Already registered by another copy of the library.
  }
}

/** One rectangle per bar. */
function barsPath(rects: BarRect[], radius: number): Path2D {
  const path = new Path2D();
  for (const bar of rects) {
    if (radius > 0 && typeof path.roundRect === "function") {
      path.roundRect(
        bar.x,
        bar.y,
        bar.width,
        bar.height,
        Math.min(radius, bar.width / 2, bar.height / 2)
      );
    } else {
      path.rect(bar.x, bar.y, bar.width, bar.height);
    }
  }
  return path;
}

/** One closed shape: along the top of every bar, then back along the bottoms. */
function linePath(rects: BarRect[]): Path2D {
  const path = new Path2D();
  for (const bar of rects) {
    path.lineTo(bar.x + bar.width / 2, bar.y);
  }
  for (let index = rects.length - 1; index >= 0; index -= 1) {
    const bar = rects[index];
    if (bar) {
      path.lineTo(bar.x + bar.width / 2, bar.y + bar.height);
    }
  }
  path.closePath();
  return path;
}

/** One open line through the points, to be stroked. */
function scopePath(points: ScopePoint[]): Path2D {
  const path = new Path2D();
  for (const point of points) {
    path.lineTo(point.x, point.y);
  }
  return path;
}

/** The options of `attachWaveformCanvas`: the peaks or a live signal, the stretch shown and the played share, the variant, the bars' size, and how the drawing moves. */
export interface WaveformCanvasOptions {
  /** Space between bars, in CSS pixels, snapped to whole device pixels. @default 1 */
  barGap?: number;
  /** Bar corner radius, in CSS pixels. Defaults to the `--waveform-bar-radius` CSS length. */
  barRadius?: number;
  /** Bar width, in CSS pixels, snapped to whole device pixels. @default 2 */
  barWidth?: number;
  /** Length of the audio, in the unit `range` is in. */
  duration: number;
  /** Visual gain applied to the levels before they are drawn. @default 1 */
  gain?: number;
  /** What the bars do while there is no signal, outside the scrolling mode. @default "none" */
  idle?: WaveformIdle;
  /** A live signal, followed instead of `peaks`: levels 0…1, or raw samples for `scope`. */
  levels?: Source<ArrayLike<number>>;
  /** Thickness of the `scope` trace, in CSS pixels. @default 1.5 */
  lineWidth?: number;
  /** Whether the audio is still on its way: the bars sweep. */
  loading?: boolean;
  /** Shortest bar, in CSS pixels. @default 2 */
  minBarHeight?: number;
  /** Makes the drawing symmetric around the middle. */
  mirrored?: boolean;
  /** How a live signal is drawn: the current levels across the width, or a scrolling record of the loudest. @default "static" */
  mode?: "scrolling" | "static";
  /** The audio's shape, when it is known upfront. */
  peaks?: WaveformPeaks;
  /** The played share, drawn in `--waveform-progress-color`. */
  played: WaveformPlayed;
  /** The stretch of the audio shown, `[start, end]` in `duration` units. */
  range: readonly [number, number];
  /** Whether motion is reduced: a moving waveform repaints four times a second at most. */
  reducedMotion?: boolean;
  /** How fast the scrolling mode moves, in CSS pixels per second. @default 60 */
  scrollSpeed?: number;
  /** `mirror`, `bars`, `line`, or `scope` for raw samples. @default "mirror" */
  variant?: WaveformVariant;
}

/**
 * Draws a waveform on `canvas`, laid out on the device pixel grid: as many
 * bars as fit its width, every edge on a physical pixel, so it stays sharp
 * at any pixel density and zoom level. It paints only when something
 * changed, and not at all while it is off screen. The played part is drawn
 * in the `--waveform-progress-color` CSS color and the rest in
 * `--waveform-color`, both the text color by default. Returns what stops it.
 */
export function attachWaveformCanvas(
  canvas: HTMLCanvasElement,
  options: WaveformCanvasOptions
): () => void {
  const context = canvas.getContext("2d");
  if (!context || typeof ResizeObserver === "undefined") {
    return () => undefined;
  }
  const { barRadius, duration, levels: live, peaks, played, range } = options;
  const barGap = options.barGap ?? 1;
  const barWidth = options.barWidth ?? 2;
  const gain = options.gain ?? 1;
  const idle = options.idle ?? "none";
  const lineWidth = options.lineWidth ?? 1.5;
  const loading = options.loading ?? false;
  const minBarHeight = options.minBarHeight ?? 2;
  const mirrored = options.mirrored ?? false;
  const mode = options.mode ?? "static";
  const reducedMotion = options.reducedMotion ?? false;
  const scrollSpeed = options.scrollSpeed ?? 60;
  const variant = options.variant ?? "mirror";
  registerBarRadiusProperty();
  let layout: BarLayout | null = null;
  let engine: LevelsEngine | null = null;
  let history: LevelHistory | null = null;
  /** The file's shape over the shown stretch, when it is drawn as it is rather than live. */
  let envelope: PeakEnvelope | null = null;
  /** A live record's levels, carried over when a resize starts a new one. */
  let previousHistory: Float32Array | undefined;
  /** Bitmap px per CSS px: the pixel density, unless the bitmap had to be capped. */
  let bitmapRatio = window.devicePixelRatio || 1;
  let shape = new Path2D();
  let radius = 0;
  let strokeWidth = 0;
  let input: ArrayLike<number> | undefined = live?.getSnapshot();
  // Whether the bars must be laid out again before the next paint.
  let stale = true;
  // Whether the levels may have moved since the shape was built.
  let moving = true;
  // A resize must repaint at once, whatever would otherwise wait.
  let urgent = false;
  let visible = true;
  let clock = 0;
  let running = false;
  let unpaintedMs = 0;
  let sincePaintMs = Number.POSITIVE_INFINITY;

  /** Sets up what the bars follow: the file as it is, a live record, or live levels. */
  const prepareLevels = (grid: BarLayout, pixelRatio: number) => {
    engine = null;
    envelope = null;
    history = null;
    if (variant === "scope") {
      return;
    }
    if (!(live || loading)) {
      // A file's shape is known: drawn as it is, with nothing to animate.
      const [from, to] = rangeShares(range, duration);
      envelope = fitPeaks(peaks ?? [], from, to, {
        high: new Float32Array(grid.count),
        low: new Float32Array(grid.count),
      });
      return;
    }
    if (live && mode === "scrolling") {
      // One entry more than fits: the newest slides in as the oldest slides
      // out. From the middle outwards, each side shows half as many.
      const pitch = grid.pitch / pixelRatio;
      history = createLevelHistory(
        (mirrored ? Math.ceil(grid.count / 2) : grid.count) + 1,
        (pitch / Math.max(scrollSpeed, 1)) * MS_PER_SECOND,
        previousHistory
      );
      return;
    }
    engine = createLevelsEngine({
      count: grid.count,
      gain,
      idle,
      loading,
      minLevel: 0,
      mirrored,
      reducedMotion,
    });
  };

  const measure = () => {
    stale = false;
    const pixelRatio = bitmapRatio;
    layout = barLayout({
      barGap,
      barWidth,
      height: canvas.height,
      minBarHeight,
      pixelRatio,
      variant,
      width: canvas.width,
    });
    radius =
      (barRadius ??
        (Number.parseFloat(
          getComputedStyle(canvas).getPropertyValue(BAR_RADIUS_PROPERTY)
        ) ||
          0)) * pixelRatio;
    strokeWidth = lineWidth * pixelRatio;
    previousHistory = history?.levels;
    prepareLevels(layout, pixelRatio);
    moving = true;
  };

  /** Where the bars are now. Sets `running` while they are still moving. */
  const place = (grid: BarLayout): BarRect[] => {
    if (envelope) {
      return envelopeRects(envelope, grid);
    }
    if (history) {
      running = history.step(performance.now());
      const progress = reducedMotion ? 1 : history.progress;
      return mirrored
        ? mirroredScrollRects(history.levels, progress, grid)
        : barRects(
            history.levels,
            grid,
            scrollShift(history.levels.length, progress, grid)
          );
    }
    if (engine) {
      engine.step(clock, input);
      running = !engine.settled;
      return barRects(engine.levels, grid);
    }
    return [];
  };

  /** Move the levels on by `elapsedMs` and rebuild the shape. Returns `true` while they are still moving. */
  const advance = (elapsedMs: number): boolean => {
    if (!layout) {
      return false;
    }
    clock += elapsedMs;
    running = false;
    if (variant === "scope") {
      shape = scopePath(
        scopePoints(input ?? [], {
          gain,
          height: layout.height,
          inset: strokeWidth,
          width: layout.width,
        })
      );
      return false;
    }
    const rects = place(layout);
    shape = variant === "line" ? linePath(rects) : barsPath(rects, radius);
    return running;
  };

  /** Ink the shape in `color`, between two columns of the bitmap. */
  const ink = (color: string, from: number, to: number) => {
    if (to <= from) {
      return;
    }
    context.save();
    context.beginPath();
    context.rect(from, 0, to - from, canvas.height);
    context.clip();
    if (variant === "scope") {
      context.lineJoin = "round";
      context.lineWidth = strokeWidth;
      context.strokeStyle = color;
      context.stroke(shape);
    } else {
      context.fillStyle = color;
      context.fill(shape);
    }
    context.restore();
  };

  const draw = () => {
    context.clearRect(0, 0, canvas.width, canvas.height);
    const computed = getComputedStyle(canvas);
    const color =
      computed.getPropertyValue("--waveform-color").trim() || computed.color;
    const progressColor =
      computed.getPropertyValue("--waveform-progress-color").trim() || color;
    // Split on a whole pixel: no column ever blends the two colors.
    const split = Math.round(played.get() * canvas.width);
    ink(progressColor, 0, split);
    ink(color, split, canvas.width);
  };

  const task = createFrameTask((elapsedMs) => {
    const mustPaint = urgent;
    urgent = false;
    if (!(visible || mustPaint)) {
      return false;
    }
    unpaintedMs += elapsedMs;
    sincePaintMs += elapsedMs;
    const throttled =
      reducedMotion && moving && sincePaintMs < REDUCED_MOTION_INTERVAL_MS;
    if (throttled && !mustPaint) {
      return true;
    }
    if (stale) {
      measure();
    }
    if (moving) {
      moving = advance(unpaintedMs);
    }
    unpaintedMs = 0;
    sincePaintMs = 0;
    draw();
    return moving;
  });

  // The bar radius is read from CSS: lay out again when it may have changed.
  const invalidate = () => {
    stale = true;
    task.wake();
  };

  const resize = (entry: ResizeObserverEntry) => {
    const pixelRatio = window.devicePixelRatio || 1;
    const exact = entry.devicePixelContentBoxSize?.[0];
    const fullWidth = bitmapLength(
      entry.contentRect.width,
      pixelRatio,
      exact?.inlineSize
    );
    const fullHeight = bitmapLength(
      entry.contentRect.height,
      pixelRatio,
      exact?.blockSize
    );
    const cap = Math.min(
      1,
      MAX_BITMAP_SIDE / Math.max(fullWidth, 1),
      MAX_BITMAP_SIDE / Math.max(fullHeight, 1)
    );
    const width = Math.max(1, Math.floor(fullWidth * cap));
    const height = Math.max(1, Math.floor(fullHeight * cap));
    bitmapRatio =
      entry.contentRect.width > 0
        ? width / entry.contentRect.width
        : pixelRatio * cap;
    if (canvas.width !== width || canvas.height !== height) {
      canvas.width = width;
      canvas.height = height;
    }
    // Resizing clears the bitmap: repaint now, before the browser shows it.
    stale = true;
    urgent = true;
    task.flush();
  };

  // A resize is drawn on the next frame, still before it is shown: drawing
  // it in the observer's callback changes the canvas inside the layout pass
  // that measured it.
  let resizeFrame = 0;
  const resizeObserver = new ResizeObserver(([entry]) => {
    if (entry) {
      cancelAnimationFrame(resizeFrame);
      resizeFrame = requestAnimationFrame(() => resize(entry));
    }
  });
  // Observing again reports the size afresh.
  const observe = () => {
    resizeObserver.unobserve(canvas);
    try {
      resizeObserver.observe(canvas, { box: "device-pixel-content-box" });
    } catch {
      // Device pixel sizes aren't reported here: CSS pixel sizes will do.
      resizeObserver.observe(canvas);
    }
  };
  observe();

  const themeObserver = new MutationObserver(invalidate);
  themeObserver.observe(document.documentElement, {
    attributeFilter: THEME_ATTRIBUTES,
    attributes: true,
  });

  const abort = new AbortController();
  const { signal } = abort;
  // A zoom, or a move to another screen, changes the pixel density without
  // resizing the canvas in CSS pixels.
  const watchPixelRatio = () => {
    matchMedia(`(resolution: ${window.devicePixelRatio}dppx)`).addEventListener(
      "change",
      () => {
        watchPixelRatio();
        observe();
      },
      { once: true, signal }
    );
  };
  if (typeof matchMedia === "function") {
    watchPixelRatio();
    matchMedia("(prefers-color-scheme: dark)").addEventListener(
      "change",
      invalidate,
      { signal }
    );
  }

  const stopObservingVisibility = observeVisibility(canvas, (next) => {
    visible = next;
    if (next) {
      task.wake();
    }
  });
  const unsubscribePlayed = played.subscribe(task.wake);
  const unsubscribeLevels = live?.subscribe(() => {
    input = live.getSnapshot();
    if (history) {
      // The record follows the signal, not the paints: it stays true while
      // the canvas is off screen or holds its frames back.
      const now = performance.now();
      history.feed(clampUnit(loudest(input) * gain), now);
      history.step(now);
    }
    moving = true;
    task.wake();
  });

  return () => {
    task.stop();
    abort.abort();
    cancelAnimationFrame(resizeFrame);
    resizeObserver.disconnect();
    themeObserver.disconnect();
    stopObservingVisibility();
    unsubscribePlayed();
    unsubscribeLevels?.();
  };
}

/**
 * The audio's shape, one entry per slice of it: either a level per slice
 * (0…1, drawn the same above and below the middle) or the lowest and highest
 * sample of each slice (-1…1), which draws the waveform as it really is,
 * lopsided where the audio is.
 */
export type WaveformPeaks =
  | ArrayLike<number>
  | { max: ArrayLike<number>; min: ArrayLike<number> };

/** Where each bar reaches above and below the middle: `high` 0…1 up, `low` 0…-1 down. */
export interface PeakEnvelope {
  high: Float32Array;
  low: Float32Array;
}

const clampSample = (value: number) => Math.min(1, Math.max(-1, value));

/** How many entries `peaks` holds. */
export function peakCount(peaks: WaveformPeaks): number {
  return "max" in peaks
    ? Math.min(peaks.max.length, peaks.min.length)
    : peaks.length;
}

/** The highest and lowest sample of entry `index`. */
function peakAt(peaks: WaveformPeaks, index: number): [number, number] {
  if ("max" in peaks) {
    return [
      clampSample(peaks.max[index] ?? 0),
      clampSample(peaks.min[index] ?? 0),
    ];
  }
  const level = Math.min(1, Math.abs(peaks[index] ?? 0));
  return [level, -level];
}

/**
 * Fits the stretch of `peaks` from `from` to `to` (shares of the whole, 0…1)
 * to one high and one low per bar of `envelope`. With more entries than bars,
 * each bar keeps the highest and the lowest of its slice, so a transient
 * never disappears between bars; with fewer, it blends its two nearest
 * entries so the shape stays smooth. Outside the data, bars are silent.
 */
export function fitPeaks(
  peaks: WaveformPeaks,
  from: number,
  to: number,
  envelope: PeakEnvelope
): PeakEnvelope {
  const { high, low } = envelope;
  const bars = high.length;
  const count = peakCount(peaks);
  high.fill(0);
  low.fill(0);
  if (count === 0 || bars === 0 || !(to > from)) {
    return envelope;
  }
  const first = from * count;
  const span = ((to - from) * count) / bars;
  for (let bar = 0; bar < bars; bar += 1) {
    const start = first + bar * span;
    const end = start + span;
    if (span >= 1) {
      const begin = Math.max(0, Math.floor(start));
      const stop = Math.min(count, Math.max(begin + 1, Math.floor(end)));
      let top = 0;
      let bottom = 0;
      for (let index = begin; index < stop; index += 1) {
        const [upper, lower] = peakAt(peaks, index);
        top = Math.max(top, upper);
        bottom = Math.min(bottom, lower);
      }
      high[bar] = top;
      low[bar] = bottom;
      continue;
    }
    const at = (start + end) / 2 - 0.5;
    if (at < -0.5 || at > count - 0.5) {
      continue;
    }
    const before = Math.min(count - 1, Math.max(0, Math.floor(at)));
    const after = Math.min(count - 1, before + 1);
    const blend = Math.min(1, Math.max(0, at - before));
    const [upperFrom, lowerFrom] = peakAt(peaks, before);
    const [upperTo, lowerTo] = peakAt(peaks, after);
    high[bar] = upperFrom + (upperTo - upperFrom) * blend;
    low[bar] = lowerFrom + (lowerTo - lowerFrom) * blend;
  }
  return envelope;
}

/**
 * The shares of the whole audio that the stretch `range` covers, for
 * `fitPeaks`: `[start, end]` in `duration` units becomes `[from, to]` in 0…1.
 */
export function rangeShares(
  range: readonly [number, number],
  duration: number
): [number, number] {
  return duration > 0 ? [range[0] / duration, range[1] / duration] : [0, 1];
}

/** A level per entry of the stretch from `from` to `to`: how far each slice reaches either way. */
export function peakMagnitudes(
  peaks: WaveformPeaks,
  from: number,
  to: number,
  count: number
): Float32Array {
  const { high, low } = fitPeaks(peaks, from, to, {
    high: new Float32Array(Math.max(0, count)),
    low: new Float32Array(Math.max(0, count)),
  });
  return high.map((top, index) => Math.max(top, -(low[index] ?? 0)));
}

/** A point of the trace, in px. */
export interface ScopePoint {
  x: number;
  y: number;
}

/** The box `scopePoints` draws into, in px, its inset, and the gain applied to the samples. */
export interface ScopeOptions {
  /** Visual gain applied to the samples. */
  gain: number;
  /** Bitmap height, in device pixels. */
  height: number;
  /** Room kept above and below, so the line's own thickness stays inside. */
  inset: number;
  /** Bitmap width, in device pixels. */
  width: number;
}

/**
 * Where a line through `samples` (-1…1 each) goes: left to right across the
 * width, around the middle of the height. More samples than pixel columns are
 * thinned out; too few to draw a line give a flat one.
 */
export function scopePoints(
  samples: ArrayLike<number>,
  { gain, height, inset, width }: ScopeOptions
): ScopePoint[] {
  const middle = height / 2;
  const { length } = samples;
  if (length < 2 || width <= 0) {
    return [
      { x: 0, y: middle },
      { x: Math.max(0, width), y: middle },
    ];
  }
  const reach = Math.max(0, middle - inset);
  const stride = Math.max(1, Math.floor(length / width));
  const points: ScopePoint[] = [];
  for (let index = 0; index < length; index += stride) {
    const sample = Math.min(1, Math.max(-1, (samples[index] ?? 0) * gain));
    points.push({
      x: (index / (length - 1)) * width,
      y: middle - sample * reach,
    });
  }
  return points;
}

import { waveform } from "./waveform";
import { createParts } from "@ui-sdk/vue/primitive";
import { defineComponent, h } from "vue";

/** Which element each part is. */
const parts = createParts(waveform, {
  bar: "span",
  bars: "div",
  canvas: "canvas",
  control: "div",
  hover: "div",
  input: "input",
  marker: "div",
  playhead: "div",
  region: "div",
  regionEnd: "div",
  regionEndInput: "input",
  regionStart: "div",
  regionStartInput: "input",
  root: "div",
  thumb: "div",
});

const NAMING = ["aria-describedby", "aria-label", "aria-labelledby"] as const;

/** The accessible name given to a part goes to the input it holds. */
const nameOf = (attrs: Record<string, unknown>) => {
  const naming: Record<string, unknown> = {};
  const rest: Record<string, unknown> = { ...attrs };
  for (const key of NAMING) {
    naming[key] = rest[key];
    delete rest[key];
  }
  return { naming, rest };
};

/**
 * The seekable surface: a press jumps to the pointer and a drag scrubs. It
 * holds the native `<input type="range">` that takes focus, handles the
 * keyboard and carries the accessible name. Leave it out for a waveform that
 * is only shown.
 */
const Control = defineComponent(
  (
    props: { getAriaValueText?: (value: number, duration: number) => string },
    { attrs, slots }
  ) =>
    () => {
      const { naming, rest } = nameOf(attrs);
      return h(parts.Control, rest as never, {
        default: (scope: object) => [
          slots.default?.(scope),
          h(parts.Input, {
            ...naming,
            getAriaValueText: props.getAriaValueText,
          } as never),
        ],
      });
    },
  { inheritAttrs: false, name: "WaveformControl", props: ["getAriaValueText"] }
);

/** The levels as a fixed number of elements, one `Waveform.Bar` each, styled in plain CSS from `--waveform-level`. */
const Bars = defineComponent(
  (props: { count?: number }, { attrs, slots }) =>
    () => {
      const count = props.count ?? 24;
      return h(parts.Bars, { ...attrs, count } as never, {
        default: () =>
          Array.from({ length: count }, (_, index) =>
            slots.default
              ? slots.default({ count, index })
              : h(parts.Bar, { index, key: index } as never)
          ),
      });
    },
  { inheritAttrs: false, name: "WaveformBars", props: ["count"] }
);

/** Resizes one edge of a region, by dragging or from the keyboard through its native input. */
const RegionHandle = defineComponent(
  (
    props: {
      edge: "end" | "start";
      getAriaValueText?: (value: number, duration: number) => string;
      region: string;
    },
    { attrs, slots }
  ) =>
    () => {
      const { naming, rest } = nameOf(attrs);
      const start = props.edge === "start";
      return h(
        start ? parts.RegionStart : parts.RegionEnd,
        { ...rest, region: props.region } as never,
        {
          default: (scope: object) => [
            slots.default?.(scope),
            h(start ? parts.RegionStartInput : parts.RegionEndInput, {
              ...naming,
              getAriaValueText: props.getAriaValueText,
              region: props.region,
            } as never),
          ],
        }
      );
    },
  {
    inheritAttrs: false,
    name: "WaveformRegionHandle",
    props: ["edge", "getAriaValueText", "region"],
  }
);

export const Waveform = {
  Bar: parts.Bar,
  Bars,
  Canvas: parts.Canvas,
  Control,
  Hover: parts.Hover,
  Marker: parts.Marker,
  Playhead: parts.Playhead,
  Region: parts.Region,
  RegionHandle,
  Root: parts.Root,
  Thumb: parts.Thumb,
};
